window.BUHSTART_ARTICLES["novosti-zakonodatelstva-30-07"] = {"tag":"Новости законодательства","title":"Новости законодательства 30 07","date":"30 июля 2026","blocks":[{"t":"h","text":"На модели размер S | рост 176 см"},{"t":"h","text":"ОБХВАТ ГРУДИ 88 СМ, ТАЛИИ 60 СМ, БЕДЕР 87 СМ"},{"t":"p","text":"Юбка в длине мини из эластичного хлопка. Двуслойный дизайн с подкладкой в виде шорт. Застежка на потайную молнию сбоку."},{"t":"p","text":"Артикул: 9529-578"}],"section":"news","preview":"Новости законодательства 13.07–19.07.2026","coverImage":"uploads/articles/novosti-zakonodatelstva-30-07-cover.svg"};
window.BUHSTART_ARTICLES["novosti-13-19-07-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 13.07–19.07.2026","date":"20 июля 2026","blocks":[{"t":"h","text":"1. Новые коды в ЕГРН"},{"t":"p","text":"С 15 августа 2026 года налоговая меняет коды оснований для учёта в ЕГРН. Это техническое обновление для запросов и выписок."},{"t":"h","text":"2. ЕГРН пополнится новыми данными"},{"t":"p","text":"В реестр налогоплательщиков добавят сведения о международных компаниях, иностранцах и крупнейших налогоплательщиках. У иностранных фирм теперь будут указывать больше деталей: руководителя, вид деятельности, банк. Часть старых оснований учёта уберут."},{"t":"h","text":"3. Хотят отменить лимит по страховым взносам"},{"t":"p","text":"Депутаты предлагают платить 30% со всех выплат сотрудникам без ограничений — сейчас после превышения лимита ставка 15,1%. Для льготников (ИТ, НКО, ОЭЗ) хотят зафиксировать единую ставку 7,6%."},{"t":"h","text":"4. Новая декларация по ЕСХН"},{"t":"p","text":"ИП на ЕСХН больше не включают проценты по вкладам в облагаемый доход — теперь это только НДФЛ. В декларации появятся строки для фиксированных взносов, в том числе 1% с дохода сверх 300 тыс. руб. Если утвердят, новая форма будет действовать с отчётности за 2026 год."},{"t":"h","text":"5. Обновили формы для вычетов НДФЛ"},{"t":"p","text":"С 1 сентября 2026 года меняются бланки заявлений на инвестиционный вычет и вычет на долгосрочные сбережения в упрощённом порядке. Старые формы перестанут действовать."},{"t":"h","text":"6. Маркировка для спортивного питания"},{"t":"p","text":"В ЕАЭС вводят обязательную маркировку продуктов для спортсменов. Каждая страна сама решит, когда и как её внедрять, но уведомит ЕЭК за полгода."},{"t":"h","text":"7. Заявки в СФР на охрану труда — до 1 августа"},{"t":"p","text":"Чтобы получить финансирование на профилактику травматизма, нужно подать заявление в Социальный фонд до 1 августа. Деньги вернут, если уложиться в план и отчитаться до 15 ноября. В этом году можно возместить до 20–30% от уплаченных взносов за вычетом выплат пострадавшим. Подать можно онлайн, по почте или через МФЦ — лучше сделать это заранее, чтобы деньги пришли в этом году."}],"section":"news","range":"13.07 — 19.07.2026","preview":"Декларация по ЕСХН, формы вычетов НДФЛ, заявки в СФР до 1 августа"};
window.BUHSTART_ARTICLES["kak-nalogovaya-vidit-vash-biznes"] = {"tag":"Налоговая","title":"Как налоговая видит ваш бизнес","date":"16 июля 2026","blocks":[{"t":"p","text":"Многие предприниматели думают, что налоговая видит только отчёты, которые они сдают. На самом деле сегодня у ФНС гораздо больше информации о бизнесе, чем кажется: данные анализируются автоматически и сопоставляются из разных источников."},{"t":"h","text":"Что видит налоговая"},{"t":"p","text":"Отчётность. ФНС получает декларации, расчёты по страховым взносам, сведения о сотрудниках, данные по НДС, информацию о доходах и налогах."},{"t":"p","text":"Банковские операции. Банки обязаны соблюдать требования законодательства и при необходимости запрашивают документы по операциям клиентов. Если деятельность выглядит необычно, информация может стать основанием для дополнительного внимания контролирующих органов."},{"t":"p","text":"Сотрудников. Налоговая видит количество работников, размер заработной платы, страховые взносы и кадровую отчётность. Например, если у компании большой оборот, а официально работает один сотрудник — это может вызвать вопросы."},{"t":"p","text":"Контрагентов. ФНС сопоставляет данные между компаниями. Если ваш поставщик или подрядчик нарушает законодательство или не сдаёт отчётность, это может повлиять на оценку рисков по всей цепочке."},{"t":"p","text":"Маркетплейсы и онлайн-площадки. Налоговая получает информацию о деятельности на маркетплейсах, онлайн-кассах и электронных площадках — скрыть реальные обороты становится всё сложнее."},{"t":"h","text":"Что вызывает внимание"},{"t":"li","text":"резкий рост оборотов;"},{"t":"li","text":"отсутствие прибыли длительное время;"},{"t":"li","text":"работа без сотрудников при больших объёмах бизнеса;"},{"t":"li","text":"расхождения в отчётности;"},{"t":"li","text":"отсутствие подтверждающих документов;"},{"t":"li","text":"несоответствие расходов и доходов."},{"t":"h","text":"Нужно ли этого бояться?"},{"t":"p","text":"Нет. Если бизнес ведёт учёт, своевременно сдаёт отчётность и может подтвердить операции документами, проверки и запросы обычно проходят спокойно."},{"t":"p","text":"Сегодня налоговая видит не только цифры в декларации — она видит общую картину бизнеса: движение денег, сотрудников, контрагентов, отчётность, хозяйственные операции. Поэтому лучший способ снизить риски — не искать способы что-то скрыть, а выстроить понятный и прозрачный учёт. Когда в документах и цифрах порядок, вопросов со стороны контролирующих органов значительно меньше."}],"section":"articles"};
window.BUHSTART_ARTICLES["chto-delat-esli-prishlo-pismo-iz-fns"] = {"tag":"Налоговая","title":"Что делать, если пришло письмо из ФНС","date":"14 июля 2026","blocks":[{"t":"p","text":"Получить письмо из налоговой — стресс почти для любого предпринимателя. Сразу появляются мысли: «Проверка?», «Штраф?», «Что я сделал не так?» Но на практике большинство писем от ФНС — это обычные запросы, уведомления или требования пояснить информацию. Главное — не паниковать и не игнорировать письмо."},{"t":"h","text":"1. Внимательно прочитайте письмо"},{"t":"p","text":"Не все письма означают проблемы. ФНС может запросить документы, попросить пояснения, уведомить о задолженности, сообщить о расхождениях или пригласить на комиссию. Важно понять: что именно хочет налоговая, какой срок ответа и какие документы нужны."},{"t":"h","text":"2. Не откладывайте «на потом»"},{"t":"p","text":"Самая опасная ошибка — закрыть письмо и забыть о нём. У налоговой почти всегда есть сроки ответа. Если их пропустить, возможны штрафы, блокировка счёта, повторные запросы и усиленное внимание к бизнесу. Даже если пока не знаете, что отвечать, — письмо нужно взять в работу сразу."},{"t":"h","text":"3. Проверьте цифры и документы"},{"t":"p","text":"Часто письма приходят из-за ошибок в отчётности, расхождений по НДС, неправильных реквизитов, отсутствия документов или несоответствия доходов и расходов. Перед ответом поднимите договоры, акты, счета, выписки и отчёты — иногда проблема решается за 10 минут после проверки документов."},{"t":"h","text":"4. Не отвечайте «на эмоциях»"},{"t":"p","text":"Фраза «у нас всё нормально» для налоговой не работает. Ответ должен быть спокойным, понятным, по существу, с документами и пояснениями. Чем аккуратнее подготовлен ответ, тем меньше дополнительных вопросов возникает."},{"t":"h","text":"5. Если не уверены — подключите бухгалтера"},{"t":"p","text":"Иногда письмо кажется простым, но за ним могут скрываться серьёзные риски — особенно если речь о больших суммах, НДС, дроблении бизнеса, работе с самозанятыми или подозрительных контрагентах. Лучше потратить время на проверку сейчас, чем потом разбираться со штрафами и блокировками."},{"t":"p","text":"Главное — помнить: письмо из ФНС не равно катастрофе. Чаще всего налоговая просто хочет получить пояснения или убедиться, что в отчётности всё сходится. Спокойствие, документы и порядок в учёте решают большинство вопросов."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-06-12-07-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 06.07–12.07.2026","date":"14 июля 2026","blocks":[{"t":"h","text":"1. Малый бизнес: выросло число компаний"},{"t":"p","text":"ФНС обновила список малых и средних предприятий. Теперь в нём 6,6 млн компаний — на 222,5 тыс. больше, чем в прошлом году. Реестр помогает государству оказывать поддержку, а предпринимателям — проверять надёжность партнёров. Данные обновлены по доходам и штату за 2025 год."},{"t":"h","text":"2. УСН: новый платёж при ввозе товаров можно списать в расходы"},{"t":"p","text":"С 1 июля для ввоза товаров из стран ЕАЭС, кроме Беларуси, ввели обязательный обеспечительный платёж. Налоговая разъяснила: компании на УСН, которые платят НДС по ставке 5% или 7% либо освобождены от него, могут включить этот платёж в свои расходы."},{"t":"h","text":"3. Маркировка: за продажу без QR-кода будут штрафовать чаще"},{"t":"p","text":"Роспотребнадзор хочет ужесточить контроль за БАДами, пивом, напитками и антисептиками. Планируют ввести 18 новых маячков риска на основе данных системы «Честный знак». Например, если объём продаж без проверки кода превысит норму — для пива 350%, для напитков всего 10%, — это станет сигналом для проверки."},{"t":"h","text":"4. Стажировки: новый закон для молодых специалистов"},{"t":"p","text":"Госдума приняла закон о стажировках, он вступает в силу с марта 2027 года."},{"t":"li","text":"Студентов и выпускников будут брать на стажировку по срочному договору до полугода — в течение года после получения диплома."},{"t":"li","text":"Работодатель обязан закрепить за стажёром наставника."},{"t":"li","text":"После успешной стажировки сотрудника можно взять на постоянную работу без испытательного срока."},{"t":"h","text":"5. Благотворительность: НДС не спишешь в расходы"},{"t":"p","text":"Если компания передаёт товары в рамках благотворительности — это операция без НДС, — то ранее принятый к вычету НДС по этим товарам нужно восстановить и заплатить. Учесть восстановленный налог в расходах для снижения налога на прибыль нельзя: это приравнивается к безвозмездной передаче."},{"t":"h","text":"6. Банкротство: новый механизм спасения бизнеса"},{"t":"p","text":"Принят масштабный закон о банкротстве, он начнёт действовать через год. Появилась реструктуризация долгов — процедура для восстановления бизнеса, если договориться с кредиторами до суда не вышло. Для компаний с активами свыше 1 млрд рублей ввели комплексное соглашение: если большинство кредиторов «за», а меньшинство против, суд может утвердить сделку для всех, но с гарантиями, что меньшинство не останется в проигрыше."}],"section":"news","range":"06.07 — 12.07.2026","preview":"Маркировка, благотворительность и НДС, новый механизм банкротства"};
window.BUHSTART_ARTICLES["glavnie-oshibki-predprinimatelei-v-nalogah"] = {"tag":"Налоги","title":"Главные ошибки предпринимателей в налогах","date":"10 июля 2026","blocks":[{"t":"p","text":"Многие проблемы с налогами начинаются не из-за «схем» или умышленного нарушения, а из-за обычного хаоса в бизнесе. Предприниматель продаёт, нанимает людей, запускает рекламу, а налоговый учёт откладывает «на потом». И именно это «потом» становится дорогим."},{"t":"h","text":"1. Принимать деньги «просто на карту»"},{"t":"p","text":"Кажется удобно: клиент перевёл — и всё. Но для налоговой регулярные поступления на личную карту выглядят как предпринимательская деятельность без учёта доходов, особенно если переводы идут постоянно от разных людей. Риск: доначисления налогов, штрафы и вопросы от банка."},{"t":"h","text":"2. Выбирать систему налогообложения наугад"},{"t":"p","text":"«Все работают на УСН 6% — и я буду». Но одному бизнесу выгоднее «Доходы», другому — «Доходы минус расходы», а кому-то вообще нужен патент или ООО с НДС. Ошибка в выборе системы может каждый месяц «съедать» прибыль."},{"t":"h","text":"3. Не разделять личные и бизнес-деньги"},{"t":"p","text":"Когда с расчётного счёта оплачиваются кофе, отпуск и личные покупки, бухгалтерия превращается в квест. В итоге предприниматель сам не понимает: сколько зарабатывает бизнес, где прибыль и почему денег нет."},{"t":"h","text":"4. Работать без документов"},{"t":"p","text":"«Мы же договорились на словах». Пока всё хорошо — проблем нет. Но если клиент не оплатил, поставщик подвёл или пришла проверка, отсутствие договора и актов становится большой проблемой. Документы — это не формальность, это защита бизнеса."},{"t":"h","text":"5. Забывать про отчёты и сроки"},{"t":"p","text":"Налоги любят дисциплину. Даже если бизнес временно не работает, отчётность часто всё равно нужно сдавать. Одна пропущенная дата — штраф, блокировка счёта или требование от налоговой."},{"t":"h","text":"6. Думать, что бухгалтер нужен только «для отчётов»"},{"t":"p","text":"Хороший бухгалтер — это не человек, который просто отправляет декларации. Это человек, который помогает не переплачивать налоги, видеть реальные цифры, избегать ошибок и спокойно проходить проверки."},{"t":"p","text":"Главная ошибка в налогах — не задавать вопросы вовремя. Потому что исправлять всегда дороже, чем сразу делать правильно."}],"section":"articles"};
window.BUHSTART_ARTICLES["zachem-predprinimatelyu-ponimat-svoi-tsifry"] = {"tag":"Финансы","title":"Зачем предпринимателю понимать свои цифры","date":"8 июля 2026","blocks":[{"t":"p","text":"Некоторые предприниматели думают: «Главное — чтобы были клиенты». Но без понимания цифр сложно управлять бизнесом."},{"t":"h","text":"Важно знать"},{"t":"li","text":"сколько бизнес реально зарабатывает;"},{"t":"li","text":"какие расходы растут;"},{"t":"li","text":"где теряются деньги;"},{"t":"li","text":"сколько нужно платить налогов;"},{"t":"li","text":"какая услуга или товар приносит прибыль."},{"t":"p","text":"Цифры помогают принимать решения не «на ощущениях», а на фактах. А это уже влияет на прибыль и на стабильность бизнеса."}],"section":"articles"};
window.BUHSTART_ARTICLES["pochemu-predprinimateli-otkladivayut-buhgalteriyu"] = {"tag":"Бизнес","title":"Почему предприниматели откладывают бухгалтерию до последнего","date":"6 июля 2026","blocks":[{"t":"p","text":"Обычно предприниматель занимается клиентами, продажами, сотрудниками, рекламой, операционкой — и бухгалтерия часто становится задачей «потом разберёмся». Но проблема в том, что налоги и отчётность не любят «потом»."},{"t":"h","text":"Из-за этого появляются"},{"t":"li","text":"штрафы;"},{"t":"li","text":"просрочки;"},{"t":"li","text":"путаница в документах;"},{"t":"li","text":"проблемы с банками;"},{"t":"li","text":"стресс перед отчётными датами."},{"t":"p","text":"Когда учёт ведётся регулярно, бизнесу становится намного спокойнее работать."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-29-06-05-07-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 29.06–05.07.2026","date":"6 июля 2026","blocks":[{"t":"h","text":"1. Банки и налоговая начнут общаться по-новому — с 2027 года"},{"t":"p","text":"Если компания не платит налоги, налоговая будет выставлять требование в специальном реестре. Банки увидят это через защищённый канал и спишут деньги. Информация о долгах будет обновляться каждый день или быстрее."},{"t":"h","text":"2. Льготные взносы 15% теперь зависят от года"},{"t":"p","text":"Если компания на спецрежиме меняет основной вид деятельности на нельготный в течение года, право на пониженные взносы с суммы свыше 1,5 МРОТ теряется с 1 января этого года, а не с месяца смены. Придётся пересчитать взносы за весь год."},{"t":"h","text":"3. Доступ к отчётности могут закрыть по-новому"},{"t":"p","text":"Правительство обновило правила доступа к бухгалтерской отчётности в ГИРБО. Доступ могут ограничить, если данные секретные или касаются гособоронзаказа. Новые правила заработают с 2027 года, старые ограничения продолжат действовать до своего срока."},{"t":"h","text":"4. Маркетплейсы обязали делиться данными с налоговой"},{"t":"p","text":"С 1 октября 2026 года площадки будут передавать в налоговую информацию о продавцах и их договорах, но только с согласия самого продавца, и всё в электронном виде."},{"t":"h","text":"5. Единое уведомление для УСН"},{"t":"p","text":"С 30 июля 2026 года вместо нескольких старых форм нужно подавать одно универсальное уведомление: о переходе на УСН, смене объекта, отказе или прекращении деятельности."},{"t":"h","text":"6. Изменится декларация 3-НДФЛ"},{"t":"p","text":"С 1 сентября 2026 года в форму добавят вычеты за взносы по долгосрочной страховке жизни от 10 лет и за сберегательные взносы работодателя в пользу работника. Получить их можно будет за 2025 год и позже."},{"t":"h","text":"7. Импортёрам из ЕАЭС — новый платёж"},{"t":"p","text":"При ввозе товаров из Армении, Казахстана и Киргизии с 1 июля, а для Беларуси с 1 ноября, нужно вносить обеспечительный платёж до поставки. Платят его отдельной платёжкой, не в составе ЕНП, по специальному КБК за два дня до ввоза — иначе систему не пройти."},{"t":"h","text":"8. Деревянные паллеты и ящики нужно маркировать"},{"t":"p","text":"Если ввозите товар на деревянных поддонах, на них обязательна маркировка об обработке от вредителей. Без неё товар не пропустят на границе и выпишут штраф — это подтвердил Верховный суд."},{"t":"h","text":"9. Одиноким родителям хотят дать отпуск в любое время"},{"t":"p","text":"В Госдуме предложили разрешить матерям- и отцам-одиночкам, а также единственным кормильцам детей до 14 лет брать ежегодный оплачиваемый отпуск тогда, когда им удобно."},{"t":"h","text":"10. Введут официальную стажировку для новичков"},{"t":"p","text":"Законопроект прошёл первое чтение. Выпускников без опыта смогут брать на срочный трудовой договор как стажёров с наставником, а после стажировки заключать постоянный договор без испытательного срока."}],"section":"news","range":"29.06 — 05.07.2026","preview":"Маркетплейсы отчитаются перед ФНС, единое уведомление по УСН"};
window.BUHSTART_ARTICLES["kuda-utekayut-dengi-v-biznese"] = {"tag":"Финансы","title":"Куда утекают деньги в бизнесе","date":"3 июля 2026","blocks":[{"t":"p","text":"Многие предприниматели сталкиваются с ситуацией: продажи есть, обороты растут, а свободных денег всё равно не хватает. И проблема часто не в отсутствии клиентов."},{"t":"h","text":"Деньги могут незаметно «утекать» через"},{"t":"li","text":"лишние расходы;"},{"t":"li","text":"рекламу без аналитики;"},{"t":"li","text":"комиссии;"},{"t":"li","text":"скидки;"},{"t":"li","text":"неправильное ценообразование;"},{"t":"li","text":"хаос в учёте."},{"t":"p","text":"С точки зрения бухгалтерии самая большая проблема — отсутствие контроля цифр."}],"section":"articles"};
window.BUHSTART_ARTICLES["pochemu-predprinimateli-boyatsya-nalogovoi"] = {"tag":"Налоговая","title":"Почему предприниматели боятся налоговой, даже если ничего не нарушают","date":"1 июля 2026","blocks":[{"t":"p","text":"Многие предприниматели испытывают стресс, когда получают письмо или уведомление от налоговой. Даже если бизнес работает честно. Почему так происходит?"},{"t":"h","text":"Потому что предприниматель не всегда уверен"},{"t":"li","text":"всё ли правильно посчитано;"},{"t":"li","text":"нет ли ошибок в отчётности;"},{"t":"li","text":"все ли документы в порядке;"},{"t":"li","text":"не пропущены ли сроки."},{"t":"p","text":"А ещё налоговая для многих — что-то сложное и непонятное. Особенно когда бизнес растёт: появляются сотрудники, становится больше платежей, увеличиваются налоги, усложняется учёт."},{"t":"p","text":"Именно поэтому спокойствие предпринимателю даёт не отсутствие проверок, а порядок в финансах и документах. Когда бизнес понимает свои цифры, контролирует налоги и ведёт учёт системно — тревоги становится намного меньше."}],"section":"articles"};
window.BUHSTART_ARTICLES["pochemu-predprinimateli-ustayut-ne-ot-biznesa"] = {"tag":"Бизнес","title":"Почему предприниматели устают не от бизнеса, а от хаоса","date":"29 июня 2026","blocks":[{"t":"p","text":"Многие предприниматели думают, что устали от бизнеса. Но чаще всего люди устают не от работы и клиентов, а от постоянного хаоса."},{"t":"h","text":"Когда бизнес живёт в режиме"},{"t":"li","text":"налоги вспоминаются в последний момент;"},{"t":"li","text":"всё нужно контролировать самому;"},{"t":"li","text":"задачи копятся;"},{"t":"li","text":"документы теряются;"},{"t":"li","text":"деньги «куда-то уходят»."},{"t":"p","text":"Бизнес начинает забирать слишком много энергии. Самое сложное — не продажи и не развитие. Самое сложное — держать всё под контролем без системы."},{"t":"p","text":"Именно поэтому порядок в финансах, документах и процессах — это не «формальность». Это возможность работать спокойнее, принимать решения увереннее и не жить в режиме постоянного стресса."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-22-28-06-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 22.06–28.06.2026","date":"30 июня 2026","blocks":[{"t":"h","text":"1. Ставка НДС 10% на детские товары: чем подтверждать"},{"t":"p","text":"Госдума приняла поправки в НК РФ, закрепляющие перечень документов для подтверждения права на ставку 10%: сведения о сертификате или декларации о соответствии и документы, выданные по праву ЕАЭС. Закон также меняет главу об акцизах и уточняет вычет НДС при получении субсидий."},{"t":"h","text":"2. Импортёрам из ЕАЭС — обеспечительный платёж с 1 июля"},{"t":"p","text":"Импортёры из Армении, Казахстана и Киргизии обязаны вносить платёж до ввоза товаров через сервис ФНС, формируя документ о предстоящей поставке. После проверки QR-кода на границе товар пропускается."},{"t":"p","text":"С 30 июля действует новая форма декларации по косвенным налогам — с отчётности за июль. В разделах 1 и 3 добавлены строки для обеспечительного платежа и превышения сумм, введён новый раздел 4 с данными о предстоящих поставках, исключён раздел по акцизам на этиловый спирт."},{"t":"h","text":"3. Освобождение от НДС для общепита: разъяснения ФНС"},{"t":"p","text":"Освобождение применяется при одновременном соблюдении условий: доход за предыдущий год не выше 3 млрд руб., доля доходов от общепита не менее 70%, среднемесячные выплаты персоналу не ниже средней зарплаты по региону. ФНС уточнила: при продаже через объекты общепита продукции и товаров, купленных у третьих лиц, включая воду, напитки и шоколад, освобождение тоже применяется."},{"t":"h","text":"4. Новый формат заявления о ввозе товаров"},{"t":"p","text":"ФНС обновила формат заявления о ввозе товаров и уплате косвенных налогов — добавлена ставка НДС 22%."},{"t":"h","text":"5. Скидки и надбавки по травматизму на 2027 год"},{"t":"p","text":"СФР утвердил значения показателей по видам деятельности. Скидка применяется, если все показатели страхователя ниже средних по отрасли, надбавка — если выше. Заявление подаётся до 1 ноября."},{"t":"h","text":"6. Лимиты работы по ГПХ на маркетплейсах"},{"t":"p","text":"С 1 октября 2026 года вступает в силу закон о платформенной экономике. Правительство установило критерий для ГПХ-исполнителей: не более 60 часов в месяц в течение 6 месяцев подряд для одного заказчика. Ограничение действует в строительстве, логистике, торговле, клининге, общепите, риэлторстве, репетиторстве, ИТ, подборе персонала, маркетинге, такси и грузоперевозках, фитнесе и анимации."},{"t":"h","text":"7. МРОТ предложили считать от средней зарплаты"},{"t":"p","text":"В Госдуму внесён законопроект: с 1 января 2027 года установить МРОТ 51 966 руб. в месяц исходя из почасовой ставки 317 руб. МРОТ на очередной год будут определять с учётом средней зарплаты по стране, скорректированной на индекс потребительских цен. Сейчас он привязан к медианной зарплате предыдущего года с коэффициентом не ниже 48%. Регионам сохранят право устанавливать более высокий МРОТ."}],"section":"news","range":"22.06 — 28.06.2026","preview":"Освобождение для общепита, скидки по травматизму, новая методика расчёта МРОТ"};
window.BUHSTART_ARTICLES["kak-delyat-ooo-esli-partnyor-uhodit"] = {"tag":"ИП и ООО","title":"Как делят ООО, если один партнёр уходит","date":"26 июня 2026","blocks":[{"t":"p","text":"Было 50/50, один хочет выйти и забрать деньги, второй не хочет платить. Начинается долгий и дорогой спор."},{"t":"h","text":"Что по закону"},{"t":"li","text":"Если в уставе разрешён выход — участник может выйти в любой момент."},{"t":"li","text":"Ему обязаны выплатить реальную стоимость его доли: не 10 тыс. руб. уставного капитала, а процент от всех активов фирмы — деньги на счетах, оборудование, долги дебиторов."},{"t":"li","text":"Срок выплаты — 3 месяца с момента заявления. Просрочка — капают проценты (ст. 395 ГК)."},{"t":"h","text":"Главная проблема — оценка"},{"t":"p","text":"Тот, кто остаётся, хочет занизить стоимость, уходящий — завысить. Суд назначит экспертизу, и её результат будет решающим. Поэтому критически важен реальный бухучёт: если активы скрыты «серыми» схемами, уходящий получит копейки."},{"t":"p","text":"Если в уставе выход не прописан — просто так выйти нельзя. Только продать долю (с согласия других) или через суд доказывать исключение второго партнёра (ст. 10 14-ФЗ). Это сложно, дорого и долго."},{"t":"h","text":"Вывод «на берегу»"},{"t":"p","text":"Как поделите бизнес при ссоре — решает устав, написанный при регистрации. Пропишите там порядок выхода, оценки и тупиковые ситуации заранее. И держите хорошего бухгалтера."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-15-21-06-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 15.06–21.06.2026","date":"26 июня 2026","blocks":[{"t":"h","text":"1. Упрощенцам и самозанятым: переход на автоУСН"},{"t":"p","text":"С 1 числа любого месяца можно перейти на автоматизированную УСН. Зарплату в отчётах указывают за месяц начисления, даже если выплата в следующем. Все налоги и доходы видны в личном кабинете автоУСН, данные по сотрудникам передаются через банк или ЛК."},{"t":"h","text":"2. Реестр налогоплательщиков обновят"},{"t":"p","text":"С 16 июля вступает новый порядок ведения ЕГРН: меняется состав сведений для компаний, иностранцев и физлиц."},{"t":"h","text":"3. Новая декларация по НДПИ"},{"t":"p","text":"С отчётности за июнь действует обновлённая форма: из раздела 3 убрали лишние строки и подразделы, обновили штрих-коды и электронный формат."},{"t":"h","text":"4. Согласие на раскрытие налоговой тайны"},{"t":"p","text":"С 1 июля вводится временный формат согласия, в том числе для правопреемников. Документ подаётся по ТКС в виде XML."},{"t":"h","text":"5. ИП: срок уплаты 1% с доходов за 2025 год"},{"t":"p","text":"До 1 июля нужно заплатить 1% с суммы, превышающей 300 тыс. руб., максимум 300 888 руб. Фиксированные взносы за 2026 год — 57 390 руб. — платятся до 28 декабря."},{"t":"h","text":"6. Налоги на криптовалюту корректируют"},{"t":"p","text":"В первом чтении одобрен законопроект: уточняют НДФЛ и налог на прибыль по цифровым валютам, освобождают от НДС услуги обменников и депозитариев, вводят правила для майнинга и иностранных цифровых прав."},{"t":"h","text":"7. Остаток на ЕНС перейдёт наследникам"},{"t":"p","text":"С 1 января 2027 года положительный остаток с ЕНС умершего будут зачислять на счёт наследника. Переходные правила действуют уже с 10 июня 2026 года."},{"t":"h","text":"8. Ключевая ставка снижена до 14,25%"},{"t":"p","text":"С 22 июня ставка уменьшена на 0,25 процентного пункта. Инфляция замедляется."}],"section":"news","range":"15.06 — 21.06.2026","preview":"Новый ЕГРН, налоги на криптовалюту, остаток ЕНС наследникам"};
window.BUHSTART_ARTICLES["pochemu-bogatii-biznes-mozhet-bit-ubitochnim"] = {"tag":"Финансы","title":"Почему «богатый» бизнес может быть убыточным","date":"20 июня 2026","blocks":[{"t":"p","text":"Со стороны многие бизнесы выглядят очень успешными: большие обороты, много клиентов, сотрудники, офис, постоянное движение денег. Но внутри бизнес может работать… в минус. И это происходит намного чаще, чем кажется."},{"t":"h","text":"1. Оборот — это не прибыль"},{"t":"p","text":"Одна из главных ошибок предпринимателей: «Если денег проходит много — значит бизнес прибыльный». На самом деле оборот — это просто количество денег, которое прошло через бизнес. Из них ещё нужно оплатить закупки, аренду, зарплаты, рекламу, налоги, логистику, комиссии, возвраты, кредиты. И только то, что осталось после всех расходов, — это прибыль."},{"t":"h","text":"2. Почему предприниматели не замечают убытки"},{"t":"p","text":"Потому что деньги постоянно «двигаются»: сегодня пришла крупная оплата, завтра — новые закупки, потом реклама, потом налоги. Создаётся ощущение «бизнес живой, значит всё нормально». Но движение денег не всегда означает заработок."},{"t":"h","text":"3. У кого это происходит особенно часто"},{"t":"li","text":"селлеры маркетплейсов;"},{"t":"li","text":"интернет-магазины;"},{"t":"li","text":"рестораны;"},{"t":"li","text":"агентства;"},{"t":"li","text":"бизнес с большой рекламой;"},{"t":"li","text":"компании с низкой маржой."}],"section":"articles"};
window.BUHSTART_ARTICLES["pochemu-nizkii-nalog-ne-vsegda-vigodno"] = {"tag":"Налоги","title":"Почему низкий налог — не всегда выгодно","date":"20 июня 2026","blocks":[{"t":"p","text":"Многие предприниматели выбирают систему налогообложения по принципу «где меньше процент». Но в бизнесе всё намного сложнее."},{"t":"h","text":"Например"},{"t":"li","text":"низкий налог может не учитывать большие расходы;"},{"t":"li","text":"без НДС можно потерять крупных клиентов;"},{"t":"li","text":"неподходящий режим может ограничивать рост бизнеса."},{"t":"p","text":"В итоге предприниматель экономит на налоге, но теряет клиентов, прибыль и возможность развития."},{"t":"h","text":"На что важно смотреть при выборе"},{"t":"p","text":"Не только на процент налога, а ещё на реальные расходы бизнеса, работу с поставщиками, необходимость НДС, будущий рост компании и нагрузку по отчётности. Иногда более «дорогой» режим оказывается выгоднее для бизнеса в целом."}],"section":"articles"};
window.BUHSTART_ARTICLES["pochemu-sistemu-nalogooblozheniya-vazhno-peresmatrivat"] = {"tag":"Налоги","title":"Почему систему налогообложения важно пересматривать","date":"20 июня 2026","blocks":[{"t":"p","text":"Многие предприниматели выбирают налоговый режим один раз — и забывают о нём на годы. Но бизнес меняется: растут обороты, расходы, команда, количество клиентов. И система, которая была выгодна в начале, может стать невыгодной позже."},{"t":"h","text":"Что часто происходит"},{"t":"p","text":"Предприниматель продолжает работать по старой схеме и переплачивает налоги, теряет прибыль, не использует выгодные возможности. Хотя иногда достаточно просто пересчитать нагрузку и изменить режим налогообложения."},{"t":"p","text":"Поэтому бизнесу важно периодически анализировать, насколько текущая система действительно выгодна сейчас."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-08-14-06-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 08.06–14.06.2026","date":"20 июня 2026","blocks":[{"t":"h","text":"1. Налоговые уведомления через Госуслуги"},{"t":"p","text":"С 1 августа они будут приходить в личный кабинет на ЕПГУ автоматически всем зарегистрированным в ЕСИА, без отдельного согласия с электронной подписью. Исключение — те, кто ранее отказался от такого способа."},{"t":"p","text":"Уведомления, требования об уплате и решения о взыскании будут размещаться только в электронном виде, без дублирования почтой. Если отказаться от Госуслуг, документы придут по почте или в личный кабинет на сайте ФНС. Бумажную версию можно получить под расписку в налоговой или МФЦ по заявлению в течение 5 дней."},{"t":"h","text":"2. Порог доходов для НДС при УСН хотят зафиксировать"},{"t":"p","text":"Законопроект предлагает не снижать порог в 2027–2028 годах и оставить его на уровне 20 млн руб.: 2025–2028 годы — 20 млн, 2029 год — 15 млн, 2030 год — 10 млн. Это затронет более 360 тыс. малых предприятий."},{"t":"h","text":"3. Отчётность через сайт ФНС — до 1 июля 2027 года"},{"t":"p","text":"Срок пилотного проекта продлён. Исключение — декларация по НДС: её по-прежнему нужно подавать через оператора ЭДО."},{"t":"h","text":"4. Единые правила маркировки детских игрушек в ЕАЭС"},{"t":"p","text":"Самокаты, куклы, головоломки, настольные игры и другое. Каждая страна сама определяет сроки и порядок введения маркировки, уведомив ЕЭК за 6 месяцев."},{"t":"h","text":"5. Новые правила розничной продажи"},{"t":"p","text":"С 1 сентября 2026 года до 1 сентября 2032 года действуют обновлённые перечни товаров длительного пользования и непродовольственных товаров, не подлежащих обмену. При продаже через агрегатора продавец обязан размещать информацию о себе на сайте и указывать способы направления претензий. Уточнены правила продажи драгметаллов и драгоценных камней."}],"section":"news","range":"08.06 — 14.06.2026","preview":"Отчётность через сайт ФНС до 2027 года, маркировка игрушек"};
window.BUHSTART_ARTICLES["ooo-ili-ip"] = {"tag":"ИП и ООО","title":"ООО или ИП","date":"10 июня 2026","blocks":[{"t":"p","text":"ООО — это когда ваш бизнес уже не «подработка», а режим «мы тут вообще-то компанию строим». Разбираемся простым языком, что такое ООО и зачем оно нужно."},{"t":"p","text":"ООО — общество с ограниченной ответственностью. Если коротко: это отдельная компания, которая существует официально. Не вы лично продаёте товар или услуги, а именно ООО."},{"t":"h","text":"Плюсы ООО"},{"t":"p","text":"1. Вы не отвечаете всем своим имуществом. Если у бизнеса проблемы — обычно риски ограничены деньгами компании."},{"t":"p","text":"2. Можно работать с крупными клиентами. Многие компании и корпорации любят работать именно с ООО: для них это серьёзнее, надёжнее и привычнее."},{"t":"p","text":"3. Можно открыть бизнес с партнёрами. У каждого будет своя доля — удобно, если запускаете проект не в одиночку."},{"t":"p","text":"4. Легче масштабироваться. Команда, инвесторы, большие обороты, офис, сотрудники — всё это чаще строится через ООО."},{"t":"h","text":"Минусы ООО"},{"t":"p","text":"1. Больше отчётности — бухгалтерия становится не «по настроению», а обязательной."},{"t":"p","text":"2. Деньги компании — не ваши личные деньги. Нельзя просто перевести себе всё на карту: есть правила вывода денег."},{"t":"p","text":"3. Штрафы и контроль серьёзнее. Налоговая относится к ООО внимательнее, чем к ИП, поэтому документы, договоры и учёт должны быть в порядке."},{"t":"h","text":"Когда ООО реально нужно"},{"t":"p","text":"Если хотите расти, работать с компаниями, нанимать сотрудников, строить бренд, запускать серьёзный проект. А если пока продаёте свечи в интернете и делаете 3 заказа в неделю — возможно, ИП пока проще."}],"section":"articles"};
window.BUHSTART_ARTICLES["kazhdii-platit-nalogi"] = {"tag":"Налоги","title":"Каждый платит налоги","date":"8 июня 2026","blocks":[{"t":"p","text":"Каждый платит налоги. Если ты ИП — это налог УСН или НДФЛ, смотря какую систему налогообложения выбрал. Если официальная зарплата — НДФЛ."},{"t":"p","text":"НДФЛ — полностью региональный налог: где прописан, в казну того региона он и пойдёт."},{"t":"h","text":"Как расходуется бюджет в Москве"},{"t":"li","text":"развитие транспортной системы — 20% бюджета;"},{"t":"li","text":"соцподдержка жителей — 13% (надбавки к пенсиям, пособия, выплаты на детей);"},{"t":"li","text":"образование (школы, вузы, сады) — 13%;"},{"t":"li","text":"ЖКХ, включая реновацию, — 10%;"},{"t":"li","text":"здравоохранение — 10%;"},{"t":"li","text":"благоустройство улиц — 4%."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-01-07-06-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 01.06–07.06.2026","date":"8 июня 2026","blocks":[{"t":"h","text":"1. Отчётность через сайт ФНС продлили до 1 июля 2027 года"},{"t":"p","text":"Исключение — декларация по НДС, её подают через оператора ЭДО. Пилотный проект действует с 2011 года."},{"t":"h","text":"2. Форма документа о предстоящей поставке для системы СПОТ"},{"t":"p","text":"Система действует с 1 июня и регулирует ввоз товаров из стран ЕАЭС автотранспортом. Импортёры сообщают о поставке через сервис ФНС, вносят данные о грузе и транспорте, а с 1 июля — с 1 ноября для поставок из Беларуси — обеспечительный платёж. Система выдаёт QR-код, который проверяют на границе вместе с товаросопроводительными документами."},{"t":"h","text":"3. Новая форма декларации по НДС и акцизам при импорте из ЕАЭС"},{"t":"p","text":"Вместо прежнего порядка вводится обеспечительный платёж в размере налогов со стоимости ожидаемой партии товаров. С 1 июля 2026 года отменён авансовый платёж акциза для производителей алкоголя и спиртосодержащей продукции. Приказ действует с 30 июля 2026 года — для деклараций за июль."},{"t":"h","text":"4. Расширят перечень премий, не облагаемых НДФЛ"},{"t":"p","text":"Добавят национальную премию в области будущих технологий «ВЫЗОВ» и премию Правительства РФ в области гидрометеорологии имени Е. К. Фёдорова."},{"t":"h","text":"5. Порог доходов для уплаты НДС зафиксируют на 20 млн руб."},{"t":"p","text":"Президент поручил приостановить снижение порога вместо запланированных 15 млн руб. в следующем году и 10 млн через год. Также поручено разработать концепцию бесшовного перехода бизнеса в более высокую категорию — от самозанятости до крупных компаний, предусмотреть льготы для МСП в производственной сфере и упростить отчётность."},{"t":"h","text":"6. Роскомнадзор разъяснил работу с реестром интернет-рекламы"},{"t":"li","text":"Уведомление о сборе 3% приходит при положительных начислениях за квартал; ошибки можно исправить, изменив данные."},{"t":"li","text":"Плательщики сбора — рекламораспространители и операторы рекламных систем. Рекламодатель платит, только если его подрядчик иностранное лицо."},{"t":"li","text":"Маркировка для иностранцев обязательна, если реклама нацелена на российскую аудиторию: нужен контракт с ОРД, идентификатор рекламы и отчётность."},{"t":"li","text":"В маркировке указывают реального рекламодателя, а не агентство. Иначе штраф: до 30 тыс. руб. для граждан, до 100 тыс. для должностных лиц, до 500 тыс. для юрлиц."}],"section":"news","range":"01.06 — 07.06.2026","preview":"Новые формы деклараций, премии без НДФЛ"};
window.BUHSTART_ARTICLES["ooo-kogda-biznes-uzhe-posereznee"] = {"tag":"ИП и ООО","title":"ООО: когда бизнес уже посерьёзнее","date":"5 июня 2026","blocks":[{"t":"p","text":"ООО подходит для команды, партнёров, агентств, магазинов. Плюсы: можно работать с крупными клиентами, ответственность ограничена компанией, проще масштабироваться. Минус — больше документов и отчётности."},{"t":"h","text":"Договорные конструкции"},{"t":"p","text":"Это просто способ оформить отношения между людьми и компаниями."},{"t":"li","text":"Договор услуг — «ты делаешь мне дизайн, я плачу деньги»;"},{"t":"li","text":"Договор подряда — нужен конкретный результат: сайт, ремонт, упаковка;"},{"t":"li","text":"Агентский договор — «ты продаёшь / ищешь клиентов от моего имени»;"},{"t":"li","text":"Договор поставки — «ты поставляешь товар партиями»."},{"t":"h","text":"Почему это важно"},{"t":"p","text":"«Мы договорились в телеге» — не защита. Нормальный договор — меньше рисков, штрафов и конфликтов. Особенно если работаете с маркетплейсами, нанимаете подрядчиков, берёте предоплату или масштабируете бизнес."},{"t":"p","text":"Бизнес без договора — как WB без отзывов: вроде можно, но тревожно."}],"section":"articles"};
window.BUHSTART_ARTICLES["k-chemu-dvizhetsya-malii-biznes"] = {"tag":"Бизнес","title":"К чему по анализу движется малый бизнес России в 2026 году","date":"2 июня 2026","blocks":[{"t":"li","text":"От запуска с нуля — к покупке готового. Вместо того чтобы строить бизнес с нуля (долго, дорого, рискованно при высокой ключевой ставке), предприниматели покупают уже работающие точки, чтобы сразу получить денежный поток."},{"t":"li","text":"От сложного и капиталоёмкого — к простому и быстрому. Уходят от проектов с непредсказуемой маржой в сторону «коробочных» решений: ПВЗ, арендные модели, микросервисы. Главные критерии — понятная операционка и короткий срок окупаемости."},{"t":"li","text":"От интуиции — к расчёту. Бизнес становится прагматичнее: если раньше открывали кафе «для души», то теперь выбирают ниши с гарантированным трафиком, даже если маржа скромнее."},{"t":"li","text":"В сторону сервисов с ежедневным спросом. Логистика, ИТ-аутсорсинг, туризм и городские услуги растут быстрее рынка — туда перетекают деньги и внимание инвесторов."},{"t":"li","text":"К быстрому насыщению простых ниш. Лёгкость входа создаёт обратный эффект: заходить всем в один и тот же ПВЗ или таксопарк становится опасно — конкуренция резко съедает ту самую скромную маржу."}],"section":"articles"};
window.BUHSTART_ARTICLES["organizatsionno-pravovie-formi-biznesa"] = {"tag":"ИП и ООО","title":"Организационно-правовые формы бизнеса","date":"2 июня 2026","blocks":[{"t":"p","text":"Организационно-правовые формы бизнеса — это не страшный термин из учебника, а просто способ, как именно оформлен бизнес."},{"t":"h","text":"ИП — когда работаешь сам на себя"},{"t":"p","text":"Подходит фрилансерам, экспертам, селлерам, небольшим услугам."},{"t":"li","text":"Плюсы: быстро открыть, меньше отчётности, проще выводить деньги;"},{"t":"li","text":"Минус: отвечаешь по долгам своим имуществом."}],"section":"articles"};
window.BUHSTART_ARTICLES["kak-vibrat-sistemu-nalogooblozheniya"] = {"tag":"Налоги","title":"Как выбрать систему налогообложения и не потерять деньги","date":"1 июня 2026","blocks":[{"t":"p","text":"Один из самых важных вопросов при открытии бизнеса: какую систему налогообложения выбрать? Ошибка может стоить очень дорого. Некоторые предприниматели выбирают режим «как у знакомого» или «что посоветовали в интернете»."},{"t":"h","text":"От чего зависит система налогообложения"},{"t":"li","text":"вид деятельности;"},{"t":"li","text":"расходы;"},{"t":"li","text":"количество сотрудников;"},{"t":"li","text":"обороты;"},{"t":"li","text":"работа с НДС;"},{"t":"li","text":"клиенты и поставщики."},{"t":"h","text":"Почему это важно"},{"t":"p","text":"Неправильный выбор может привести к тому, что бизнес будет платить лишние налоги, терять прибыль, сталкиваться с блокировками банка и кассовыми разрывами. Иногда предприниматель зарабатывает нормально, но из-за неподходящей системы налогообложения теряет сотни тысяч рублей в год."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-25-31-05-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 25.05–31.05.2026","date":"8 июня 2026","blocks":[{"t":"h","text":"1. Общепит на АУСН и НДС"},{"t":"p","text":"Если вы на АвтоУСН и не сдаёте отчёты о зарплате, вы всё равно можете не платить НДС в общепите. Главное, чтобы налоговая сама смогла проверить: зарплата ваших сотрудников не ниже средней по региону."},{"t":"h","text":"2. Штрафы за нулевые декларации отменят"},{"t":"p","text":"Не будут штрафовать за неподачу пустых деклараций с нулевым налогом, а обычных людей — за то, что не отчитались о продаже или дарении недвижимости: налоги всё равно посчитают сами. За опоздание с ненулевыми декларациями введут упрощённый штраф без лишних проверок."},{"t":"h","text":"3. Банки и налоговая обменяются данными по-новому"},{"t":"p","text":"Информацию о счетах за границей налоговая и банки будут передавать через систему СМЭВ. На ответ даётся 14 рабочих дней."},{"t":"h","text":"4. Как отказаться от льготной ставки НДС 5% или 7%"},{"t":"p","text":"Если вы на УСН начали платить НДС по льготной ставке только с 2026 года, отказаться можно в течение первых четырёх кварталов. Если перешли ещё в 2025 году — придётся платить так минимум три года, то есть 12 кварталов."},{"t":"h","text":"5. С 2027 года — одна декларация вместо десятков"},{"t":"p","text":"Отчётность по каждому филиалу отдельно сдавать не нужно: компания подаст единую декларацию по налогу на прибыль, перечислив все подразделения в разных листах."}],"section":"news","range":"25.05 — 31.05.2026","preview":"Общепит на АУСН без НДС, обмен данными с банками"};
window.BUHSTART_ARTICLES["sotrudnik-unyos-bazu-klientov"] = {"tag":"Бизнес","title":"Сотрудник уволился и унёс базу клиентов. Что можно сделать по закону?","date":"26 мая 2026","blocks":[{"t":"p","text":"Эта история знакома многим. Менеджер работал три года, знал всех клиентов, имел доступ к базе. Потом уволился, через месяц открыл такую же фирму и начал переманивать ваших клиентов. По закону это называется «недобросовестная конкуренция», но доказать что-то удаётся очень редко."},{"t":"h","text":"1. Объявить базу коммерческой тайной (98-ФЗ)"},{"t":"p","text":"Нужно выполнить три условия: издать приказ о коммерческой тайне; под подпись сообщить сотруднику, что именно считается тайной; на всех документах поставить пометку «Коммерческая тайна». Если хоть одно условие не выполнено — защиты нет: сотрудник ничего не нарушил, он просто унёс в голове то, что помнил."},{"t":"h","text":"2. Прописать в договоре запрет работать у конкурентов"},{"t":"p","text":"В России просто запретить нельзя — это нарушает право на труд (ст. 37 Конституции), суды такие пункты не поддерживают. Рабочий вариант — прописать не запрет, а компенсацию: «Если в течение года после увольнения уйдёте к конкуренту, вернёте часть бонуса или компенсируете расходы на обучение». Это уже денежный вопрос, и суды такое одобряют."},{"t":"h","text":"3. Уголовная статья (ст. 183 УК РФ)"},{"t":"p","text":"Наказывает за разглашение коммерческой тайны — но только если режим тайны официально действовал и есть доказательства: выгрузка из базы, логи доступа, переписка. Без этого дело не заведут."},{"t":"h","text":"Итог"},{"t":"p","text":"Защищать нужно ДО того, как наняли сотрудника, а не после увольнения. Режим тайны, подписи в договоре, разграничение доступа в CRM — это минимум, чтобы у вас вообще был шанс в суде. А если совсем коротко: на практике сделать почти ничего нельзя — поэтому многие просто нанимают менеджеров «с готовой базой»."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-18-24-05-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 18.05–24.05.2026","date":"27 мая 2026","blocks":[{"t":"h","text":"1. Новые справочники КБК с 2027 года"},{"t":"p","text":"Минфин выпустит новые перечни бюджетных кодов, действующие коды 2026 года перестанут применяться. В целом перечни похожи на текущие, но будут небольшие изменения — например, добавят коды для некоторых доходов муниципалитетов. Коды для нацпроектов сохранятся."},{"t":"h","text":"2. Налоги можно будет платить через СБП"},{"t":"p","text":"С 22 ноября 2027 года компании и ИП смогут платить налоги и другие платежи в бюджет через Систему быстрых платежей по специальной ссылке. С 1 октября 2026 года через СБП можно будет переводить деньги нотариусам, адвокатам и другим специалистам. Также СБП начнут использовать для выплат вкладчикам и переводов с зарубежными посредниками."},{"t":"h","text":"3. Возвратный лизинг — под контролем Росфинмониторинга"},{"t":"p","text":"С 31 мая 2026 года лизинговые компании обязаны сообщать о сделках возвратного лизинга с физлицами на сумму от 100 тыс. до 1 млн рублей — это когда человек сначала продаёт своё имущество лизинговой компании, а потом берёт его же обратно в лизинг. Отчётность подаётся в течение 730 дней по специальной форме с кодами 6201 или 6202."}],"section":"news","range":"18.05 — 24.05.2026","preview":"Возвратный лизинг под контролем Росфинмониторинга"};
window.BUHSTART_ARTICLES["proverka-kontragenta"] = {"tag":"Бизнес","title":"Проверка контрагента: все делают вид, что проверяют, а по факту — нет","date":"22 мая 2026","blocks":[{"t":"p","text":"Как обычно бывает: перед сделкой менеджер заходит на сайт налоговой, вбивает ИНН, видит, что компания существует и директор не под следствием, и говорит «всё ок». После этого подписывают договор на миллионы с человеком, которого видят впервые. Это не проверка — это чтобы совесть была спокойна."},{"t":"h","text":"На что реально посмотреть"},{"t":"li","text":"Арбитражные дела (kad.arbitr.ru — бесплатно, 3 минуты). Если у компании за год 10 активных исков от поставщиков — это не случайность, это стиль работы."},{"t":"li","text":"Бухгалтерию (сайт ФНС или Контур.Фокус). Компания с годовой выручкой 2 млн предлагает контракт на 15 млн? Странно."},{"t":"li","text":"Кто директор и где офис. Один директор на 30 компаний, в здании зарегистрировано 800 фирм — стоит присмотреться."},{"t":"li","text":"Долги по налогам. ФНС публикует списки должников. Если контрагент там — налоговая придёт к нему, а заодно проверит и вас."},{"t":"h","text":"Самое неприятное"},{"t":"p","text":"Мошенники обманут — полбеды. Хуже, когда налоговая говорит: «Вы не проявили осторожность» — и заставляет заплатить НДС ещё раз, потому что партнёр оказался однодневкой, а вы его не проверили. Потратить 5 минут на проверку до подписания договора — или месяц разбираться с налоговой потом. Выбирайте сами."}],"section":"articles"};
window.BUHSTART_ARTICLES["zakrit-ip-i-otkrit-zanovo"] = {"tag":"ИП и ООО","title":"Закрыть ИП и открыть заново, чтобы сэкономить на налогах?","date":"20 мая 2026","blocks":[{"t":"p","text":"С 2026 года этот номер не пройдёт. Раньше некоторые предприниматели под конец года закрывали ИП, в январе открывали новое — и счётчик доходов обнулялся, что позволяло не платить НДС. Теперь эту схему запретили, и налоговая сама научилась её вычислять."},{"t":"h","text":"Что изменилось с 2026 года"},{"t":"p","text":"Раньше ИП на УСН могли не платить НДС, пока доход не превышал 60 млн рублей. Теперь порог снизили до 20 млн. ФНС и Минфин разъяснили: доходы ИП за календарный год суммируются — даже если вы закрылись и открылись снова в том же году. Льгота привязана к человеку, а не к номеру записи в реестре."},{"t":"h","text":"Как налоговая вычисляет обман"},{"t":"p","text":"Автоматически сверяет данные ЕГРИП, отчёты онлайн-касс, банковские операции и информацию от ваших клиентов. Если после перерегистрации те же клиенты, адрес склада, телефоны, сайт и IP-адреса — налоговая это видит и собирает доказательства."},{"t":"h","text":"Что будет, если попасться"},{"t":"p","text":"Доначислят НДС за весь год, как будто закрытия не было. Плюс штраф 20% от суммы налога (40%, если докажут умысел) и пени за каждый день просрочки."},{"t":"h","text":"Если перерегистрация очень нужна"},{"t":"p","text":"Придумайте честную деловую цель до закрытия ИП: переезд в другой регион, смена сферы, реструктуризация. Откройте счета в других банках, наймите новых сотрудников, разделите процессы. Вопрос к вам: сможете ли вы доказать налоговой, что новое ИП — не просто продолжение старого?"}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-11-17-05-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 11.05–17.05.2026","date":"27 мая 2026","blocks":[{"t":"h","text":"1. ФНС разъяснила получение налоговых вычетов в течение года"},{"t":"p","text":"Вычет за обучение в кредит: можно вернуть НДФЛ с фактических затрат по справке от учебного заведения. Если аннулирован имущественный вычет по медицинским услугам, подаётся уточнённая декларация с указанием обоих вычетов, когда база использована не полностью. Основание для рассрочки на лечение — справка об оплате медуслуг."},{"t":"p","text":"Справку на обучение выдаёт ИП с лицензией или без неё, если коды ОКВЭД в ЕГРИП образовательные; самозанятый преподаватель не вправе. Справка на лечение оформляется на того, кто получает вычет, супруги могут распределить расходы по договору."},{"t":"h","text":"2. Годовой лимит сверхурочной работы повысили до 240 часов"},{"t":"p","text":"Повышение возможно при наличии коллективного договора или отраслевого соглашения. Прежние 120 часов сохраняются для работников госучреждений с внутренним совместительством более четверти месячной нормы и для сотрудников с вредными условиями труда подклассов 3.3 и 3.4."},{"t":"p","text":"Если переработка превышает 120 часов, работник получает дополнительный оплачиваемый день на диспансеризацию. Первые два часа оплачиваются в полуторном размере, последующие — в двойном; при превышении 120 часов все часы переработки оплачиваются не менее чем в двойном размере."},{"t":"h","text":"3. Представителям ИП разрешили входить в личный кабинет по доверенности"},{"t":"p","text":"Количество представителей не ограничено. Нужны квалифицированная электронная подпись физлица и машиночитаемая доверенность; по бумажной доверенности доступен только просмотр данных."},{"t":"p","text":"В личном кабинете доступны регистрация ИП и выписки из ЕГРИП, проверка данных работников, операции по ЕНС, сведения о нарушениях валютного законодательства, уведомления банков и отчёты о движении средств, информирование о рисках, заявления по ККТ и обмен бухгалтерской отчётностью."}],"section":"news","range":"11.05 — 17.05.2026","preview":"Разъяснения ФНС по обучению и лечению, новые правила оплаты переработок"};
window.BUHSTART_ARTICLES["novosti-27-04-10-05-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 27.04–10.05.2026","date":"13 мая 2026","blocks":[{"t":"h","text":"1. Новая форма декларации по налогу на игорный бизнес"},{"t":"p","text":"С 4 мая 2026 года форма меняется, отчитываться по-новому нужно начиная с июня. Срок подачи прежний — не позднее 25-го числа после каждого налогового периода. С 1 мая вводятся новые формы для регистрации объектов игорного бизнеса; касается только казино и залов игровых автоматов."},{"t":"h","text":"2. В Госдуме предложили снизить НДС с 22% до 20%"},{"t":"p","text":"По мнению автора инициативы, это поможет сдержать инфляцию, сохранить доходы граждан и поддержать бизнес."},{"t":"h","text":"3. Перечень сезонных отраслей для рассрочки по налогам дополнят"},{"t":"p","text":"Минпромторг подготовил проект: в перечень войдут производство и продажа чулочно-носочных изделий из полиамида."},{"t":"h","text":"4. Праздники и перенос выходных в 2027 году"},{"t":"p","text":"По проекту Минтруда суббота 20 февраля станет рабочей, чтобы отдохнуть три дня подряд с 21 по 23 февраля. За счёт переноса выходных 2 и 3 января удлинят отдых в ноябре и сделают свободным 31 декабря."},{"t":"li","text":"с 31 декабря 2026 года по 10 января 2027 года;"},{"t":"li","text":"с 21 по 23 февраля;"},{"t":"li","text":"с 6 по 8 марта;"},{"t":"li","text":"с 1 по 3 и с 8 по 10 мая;"},{"t":"li","text":"с 12 по 14 июня;"},{"t":"li","text":"с 4 по 7 ноября и 31 декабря 2027 года."},{"t":"h","text":"5. Новые правила оплаты выписок из ЕГРН"},{"t":"p","text":"С 16 мая 2026 года срок оплаты увеличится с 7 до 14 календарных дней после получения идентификатора начисления. Деньги вернут полностью, если запрос не получен — например, подан не по форме. Заявление о возврате адресуют Росреестру или Роскадастру, а при оформлении через Госуслуги заверяют простой электронной подписью."},{"t":"h","text":"6. Новая форма декларации по водному налогу"},{"t":"p","text":"Ставки, включая ставку для водоснабжения населения, применяются с коэффициентом 4,65 и ежегодно индексируются на коэффициент-дефлятор. Приказ вступает в силу 5 июля 2026 года."}],"section":"news","range":"27.04 — 10.05.2026","preview":"Предложение снизить НДС до 20%, новые формы по игорному бизнесу"};
window.BUHSTART_ARTICLES["vernut-13-za-kursi"] = {"tag":"Налоги","title":"Вернуть 13% за курсы","date":"май 2026","blocks":[{"t":"p","text":"Если вы оплачивали обучение — курсы, повышение квалификации, образование детей, — можно вернуть 13% через социальный налоговый вычет по НДФЛ."},{"t":"h","text":"Условия"},{"t":"li","text":"вы платите НДФЛ (официальная зарплата или ИП на ОСНО);"},{"t":"li","text":"у образовательной организации есть лицензия;"},{"t":"li","text":"есть документы об оплате: договор и чеки."},{"t":"p","text":"Вычет оформляется через декларацию 3-НДФЛ или через работодателя. Поможем посчитать сумму и подготовить документы — обращайтесь."}],"section":"articles"};
window.BUHSTART_ARTICLES["novosti-20-26-04-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 20.04–26.04.2026","date":"28 апреля 2026","blocks":[{"t":"h","text":"1. Новые правила учёта счетов-фактур"},{"t":"p","text":"С 1 апреля 2026 года правила изменились, ФНС обновила электронные форматы журналов и книг покупок и продаж. Новые форматы применяются с 1 июля 2026 года, до этого действуют временные рекомендации ФНС."},{"t":"h","text":"2. Страховые взносы для МСП предлагают снизить с 15% до 10%"},{"t":"p","text":"Сейчас 15% платят с зарплаты выше 40,5 тыс. рублей, то есть 1,5 МРОТ. Многие фирмы не могут платить такую зарплату из-за налогов, снижение ставки поможет платить больше официально. С 1 января 2026 года льготные ставки сохранились только для приоритетных отраслей — от 7,6% до 30% в зависимости от зарплаты и сферы."},{"t":"h","text":"3. Штрафы за неявку в налоговую хотят увеличить"},{"t":"li","text":"за неявку без уважительной причины — с 1 тыс. до 5 тыс. рублей;"},{"t":"li","text":"за отказ давать показания или ложь — с 3 тыс. до 7 тыс. рублей."},{"t":"p","text":"Изменения нужны в первую очередь для борьбы с серыми зарплатами и нелегальной занятостью."},{"t":"h","text":"4. Ключевая ставка снижена до 14,5%"},{"t":"p","text":"С 27 апреля 2026 года, предыдущее значение 15% действовало с марта. Годовая инфляция на 20 апреля составила 5,7%, по итогам года ожидается 4,5–5,5%. Средняя ключевая ставка по прогнозу: 13,3–14,0% до конца 2026 года, 8–10% в 2027 году, 7,5–8,5% в 2028 году."},{"t":"h","text":"5. ЦБ опроверг изменение тарифов на переводы через СБП"},{"t":"p","text":"Речь идёт об уточнениях редакционного характера: тарифы сведены в один документ, применён термин «Клиент Банка России», добавлено уточнение про НДС. Все размеры тарифов остались без изменений — для граждан переводы до 100 тыс. рублей в месяц по-прежнему бесплатны."}],"section":"news","range":"20.04 — 26.04.2026","preview":"Новые форматы книг покупок и продаж, рост штрафов за неявку в налоговую"};
window.BUHSTART_ARTICLES["novosti-13-19-04-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 13.04–19.04.2026","date":"22 апреля 2026","blocks":[{"t":"h","text":"1. Налог на игорный бизнес стал федеральным"},{"t":"p","text":"С 1 января 2026 года каждый игровой стол или автомат нужно регистрировать в налоговой по месту установки — заявление минимум за 5 дней до установки, при выбытии объекта тоже уведомить за 5 дней. С 1 мая 2026 года вступают в силу новые формы заявлений и свидетельств."},{"t":"h","text":"2. До 1 мая организации и ИП узнают тариф взносов на травматизм"},{"t":"p","text":"Его определят по основному виду деятельности на основе данных ЕГРЮЛ, ЕГРИП и Росстата на 15 апреля. Если отчётность в Росстат не подаётся, используют заявительный вид деятельности. При расхождениях с реальной работой СФР сам установит тариф."},{"t":"h","text":"3. Новая форма декларации по туристическому налогу"},{"t":"p","text":"Из неё убрали поля для КБК и добавили строки в раздел 2: тип средства размещения, льготы и другое. Декларацию сдают владельцы средств размещения из реестра, если сдавали жильё; если услуг не было — подавать не нужно. Срок за 1 квартал 2026 года — не позднее 27 апреля, за опоздание штраф и блокировка счетов."},{"t":"h","text":"4. СФР обновит формы решений и требований по персучёту"},{"t":"p","text":"Серьёзных изменений нет — например, в требование добавят QR-код для оплаты. Планируемая дата вступления — 1 июля 2026 года."},{"t":"h","text":"5. Система СПОТ с 1 июня 2026 года"},{"t":"p","text":"Система подтверждения ожидания поставки товаров. Для ввоза автотранспортом из ЕАЭС нужно оформить электронный документ о предстоящей поставке и внести обеспечительный платёж. Оператор — налоговая, контролёр — таможня. Исключения: наличные, нефть, электроэнергия, товары для личных нужд."},{"t":"li","text":"За 2 дня до ввоза сформировать ДОПП."},{"t":"li","text":"За 2 дня до ввоза внести обеспечительный платёж не менее суммы косвенных налогов."},{"t":"li","text":"Получить QR-код и передать его поставщику или перевозчику."},{"t":"li","text":"Хранить документы 5 лет."},{"t":"p","text":"Платёж не нужен крупнейшим налогоплательщикам и участникам налогового мониторинга, при продаже физлицам через электронные площадки и при ввозе давальческого сырья под переработку. Платёж зачтут при уплате косвенных налогов; если ввоз не состоялся, сумму можно отразить в декларации в течение 3 лет с даты ДОПП."}],"section":"news","range":"13.04 — 19.04.2026","preview":"Туристический налог, регистрация объектов игорного бизнеса"};
window.BUHSTART_ARTICLES["novosti-06-12-04-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 06.04–12.04.2026","date":"14 апреля 2026","blocks":[{"t":"h","text":"1. Сроки сдачи декларации 3-НДФЛ за 2025 год"},{"t":"p","text":"Подать до 30 апреля 2026 года. Это касается тех, кто продал недвижимость раньше срока, сдавал жильё, выиграл в лотерею, получил дорогие подарки не от родственников, а также ИП и нотариусов. Налог заплатить до 15 июля 2026 года, за опоздание штраф и пени. Если нужен только налоговый вычет, срок подачи не ограничен."},{"t":"h","text":"2. Закрытие и повторное открытие ИП не спасёт от НДС"},{"t":"p","text":"Для расчёта лимита учитывают весь доход за календарный год, включая периоды до закрытия и после открытия. Налоговики могут признать такие действия умышленным искажением данных и дроблением бизнеса, чтобы лишить льготы по НДС."},{"t":"h","text":"3. ФНС будет сверять декларации продавцов с отчётами маркетплейсов"},{"t":"p","text":"Система автоматически сопоставит данные о реальных продажах. Если найдут нестыковки, площадка сама предупредит продавца о рисках. Честным налогоплательщикам это поможет проходить проверки быстрее."},{"t":"h","text":"4. ФНС начнёт находить платежи без чеков"},{"t":"p","text":"В кассовые чеки добавят специальные метки из банковских переводов. Система сопоставит их и увидит транзакции, по которым нет чека."},{"t":"h","text":"5. Расширены трудовые гарантии для женщин"},{"t":"p","text":"С 1 сентября 2026 года при приёме на работу запрещено устанавливать испытательный срок женщинам с детьми до трёх лет. Раньше запрет действовал только для мам детей до полутора лет."},{"t":"h","text":"6. Земельный налог для застройщиков"},{"t":"p","text":"Компании, купившие участок под жильё, первые 3 года платят налог в двойном размере. Как только построят дом и оформят права на него, налог пересчитают по обычному коэффициенту. При реорганизации фирмы срок владения не обнуляется."}],"section":"news","range":"06.04 — 12.04.2026","preview":"Перерегистрация ИП не спасёт от НДС, поиск платежей без чеков"};
window.BUHSTART_ARTICLES["novosti-30-03-05-04-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 30.03–05.04.2026","date":"7 апреля 2026","blocks":[{"t":"h","text":"1. Признание дохода при оплате картой"},{"t":"p","text":"Если оплата картой прошла в период УСН, а деньги поступили уже на АвтоУСН, доход признаётся по кассовому методу и учитывается при расчёте базы по АвтоУСН. Пример: ИП продал товар 28 февраля и пробил чек, с 1 марта перешёл на АвтоУСН, деньги поступили 2 марта — выручка включается в базу по АвтоУСН."},{"t":"h","text":"2. Злостных нарушителей по ККТ включат в специальный реестр"},{"t":"li","text":"В чеках станет обязательным отражать информацию о безналичной транзакции."},{"t":"li","text":"Банки будут передавать в ФНС данные об операциях физлиц с юрлицами и ИП, включая переводы по СБП, и направлять покупателям чеки от ФНС."},{"t":"li","text":"Нарушителям из реестра запретят размещать предложения о дистанционной продаже товаров и услуг."},{"t":"li","text":"Появится категория организаторов массовой торговли — владельцев недвижимости, сдающих её под торговлю. Они смогут в одностороннем порядке расторгать договоры аренды при нарушении ККТ."},{"t":"h","text":"3. ФНС опровергла слухи о блокировке счетов граждан за несдачу 3-НДФЛ"},{"t":"p","text":"Приостановить операции могут только организациям, ИП, нотариусам, адвокатам и частнопрактикующим лицам, если они не сдали декларацию в течение 20 дней после срока. О блокировке всегда предупреждают заранее."},{"t":"p","text":"Отчитаться до 30 апреля должны те, кто продал имущество раньше минимального срока, получил дорогой подарок не от близкого родственника, сдавал жильё, выиграл в лотерею, имел доходы из-за рубежа, а также ИП, нотариусы и адвокаты. Уплатить налог — до 15 июля 2026 года. Штраф: 5% от суммы налога за каждый месяц просрочки, минимум 1000 руб., максимум 30%, плюс 20% от неуплаченной суммы."},{"t":"h","text":"4. Запрет на вывоз наличных и золота в ЕАЭС"},{"t":"p","text":"С 1 апреля 2026 года физлицам запрещено вывозить наличные рубли свыше эквивалента 100 тыс. долларов, юрлицам и ИП — независимо от суммы. Исключение — вывоз через аэропорты при наличии банковских выписок. Также запрещён вывоз золота в слитках весом более 100 г."},{"t":"h","text":"5. АУСН заработала в Ямало-Ненецком автономном округе"},{"t":"p","text":"С 1 апреля 2026 по 31 декабря 2027 года. Это бесконтактный режим для микробизнеса: налог рассчитывает ФНС автоматически по данным ККТ и банка, отчётности нет, плательщики освобождены от страховых взносов за себя и работников."}],"section":"news","range":"30.03 — 05.04.2026","preview":"Доход при оплате картой, АУСН в ЯНАО, блокировка счетов"};
window.BUHSTART_ARTICLES["novosti-23-29-03-2026"] = {"tag":"Законодательство","title":"Новости законодательства 23.03–29.03.2026","date":"31 марта 2026","blocks":[{"t":"h","text":"1. Декларирование доходов от майнинга — до 30 апреля"},{"t":"p","text":"Подать 3-НДФЛ за 2025 год должны ИП, добывающие криптовалюту, и физлица-майнеры. В декларацию включаются доходы от майнинга и от продажи криптовалюты."},{"t":"p","text":"ИП должны зарегистрироваться в специальном реестре ФНС — там уже более 1000 ИП. Физлица могут майнить без регистрации при потреблении электроэнергии до 6 тыс. кВт·ч в месяц. Налоговую базу определяют по рыночным котировкам криптовалют и объёмам торгов на иностранных биржах; налогоплательщик сам выбирает подходящую котировку по торговой паре."},{"t":"h","text":"2. Новая форма упрощённой налоговой декларации"},{"t":"p","text":"Можно использовать досрочно с 1 апреля 2026 года, закон вступает в силу 6 апреля. Сдают плательщики одного или нескольких налогов, не ведущие операций с движением денежных средств и объектов налогообложения. Пока приказ Минфина не отменил прежнюю форму, налоговые органы принимают оба варианта."},{"t":"h","text":"3. Туристический налог и путёвки льготников"},{"t":"p","text":"Льготные категории не облагаются туристическим налогом при предоставлении подтверждающих документов. Налог считается как 100 рублей за каждый день проживания, документы для подтверждения льготы хранят 5 лет."},{"t":"h","text":"4. Обновлённая форма РСВ"},{"t":"p","text":"Действует с 6 мая 2026 года, изменения касаются отражения условий применения пониженных тарифов для МСП. До 5 мая можно сдавать старую форму."},{"t":"h","text":"5. Лишение льготы по взносам при исключении из реестра МСП"},{"t":"p","text":"С 2026 года пониженный тариф 15% применяют только МСП из определённого перечня. Если организацию исключили из реестра, право на льготу теряется с первого числа месяца исключения. При смене основного ОКВЭД на попадающий под перечень тариф снижается с месяца изменения, при смене на не включённый — льгота теряется с месяца изменения."},{"t":"h","text":"6. Коды продтоваров со ставкой НДС 10%"},{"t":"p","text":"С 1 июля 2026 года из перечня исключат некоторые молочные продукты с заменителями и спреды."},{"t":"h","text":"7. Учёт невыплаченной при УСН зарплаты при переходе на АУСН"},{"t":"p","text":"Расходы — зарплата и страховые взносы — признаются по дате фактической оплаты. Если зарплата за период УСН выплачена после перехода на АУСН и не учтена в расходах УСН, её можно учесть в расходах при АУСН. Двойной учёт не допускается."}],"section":"news","range":"23.03 — 29.03.2026","preview":"Упрощённая декларация, туристический налог"};
window.BUHSTART_ARTICLES["novosti-16-22-03-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 16.03–22.03.2026","date":"24 марта 2026","blocks":[{"t":"h","text":"1. Ключевая ставка снижена до 15%"},{"t":"p","text":"Банк России снизил ставку на 0,5 процентного пункта, новый размер применяется с 23 марта 2026 года. По прогнозу ЦБ годовая инфляция снизится до 4,5–5,5% в 2026 году."},{"t":"h","text":"2. Минфин уточнит реквизиты для безналичных платежей в бюджет"},{"t":"p","text":"В перечень планируют добавить данные для переводов цифровых рублей: плательщик, фактический плательщик, получатель, лицевой счёт. Обновлённые правила оформления платёжек действуют с 1 апреля 2026 года."},{"t":"h","text":"3. АУСН: расходы по зарплате учитываются при фактической оплате"},{"t":"p","text":"Если зарплата и взносы начислены при УСН, а выплачены после перехода на АУСН «доходы минус расходы», их нельзя учесть при УСН — они включаются в базу АУСН в периоде фактической уплаты."},{"t":"h","text":"4. Декларация по УСН за 2025 год: что изменилось"},{"t":"p","text":"Форму обновили технически: изменили штрихкоды, убрали строки с признаком ставки, добавили строки для страховых взносов по ст. 430 НК РФ, обновили коды способа подачи. Сроки: организации — до 25 марта 2026 года, ИП — до 27 апреля. Сдать можно как по новой, так и по старой форме."},{"t":"p","text":"Сдают все организации и ИП на УСН, включая тех, кто не вёл деятельность или применяет нулевую ставку. Нулевая декларация подаётся в те же сроки; за неподачу — штраф и блокировка счетов."},{"t":"h","text":"5. НДС 10% на продтовары: корректировка перечней"},{"t":"p","text":"С 1 июля 2026 года из перечней исключат молокосодержащие продукты с заменителем молочного жира, спреды и топлёные сливочно-растительные смеси."}],"section":"news","range":"16.03 — 22.03.2026","preview":"Реквизиты для цифровых рублей, зарплата при переходе на АУСН"};
window.BUHSTART_ARTICLES["novosti-09-15-03-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 09.03–15.03.2026","date":"19 марта 2026","blocks":[{"t":"h","text":"1. Налоговой хотят расширить права при проверках"},{"t":"li","text":"Тайный покупатель онлайн: контрольные закупки дистанционно, без отдельного разрешения и уведомления прокуратуры."},{"t":"li","text":"Документарная проверка без согласования с прокуратурой, если есть данные об ущербе или угрозе."},{"t":"li","text":"Штрафы без визита: если нарушение заметили дистанционно, смогут сразу возбудить административное дело."},{"t":"h","text":"2. Декларация 3-НДФЛ за 2025 год — до 30 апреля"},{"t":"p","text":"Отчитаться обязаны те, кто продал имущество раньше минимального срока 3–5 лет, сдавал жильё в аренду, получил дорогие подарки не от родственников или выигрыши, а также ИП, нотариусы и адвокаты. Налог заплатить до 15 июля. Если налог за вас не удержали на работе — до 1 декабря 2026 года по уведомлению. Штраф за опоздание от 1000 руб. или 5% от суммы налога за каждый месяц."},{"t":"h","text":"3. Обновлена форма расчёта по страховым взносам"},{"t":"p","text":"Для МСП из приоритетных отраслей теперь можно отражать соответствие условиям для пониженного тарифа. Добавлены коды для участников технополиса «Эра» и для МСП из приоритетных отраслей; старые коды для МСП больше не применяются для льготников из приоритетных отраслей. Приказ вступает в силу 5 мая 2026 года."},{"t":"h","text":"4. Новая декларация по игорному бизнесу"},{"t":"p","text":"Применяется начиная с отчётности за июнь 2026 года."},{"t":"h","text":"5. Лимит пеней по взносам на травматизм с 1 июля 2026 года"},{"t":"p","text":"Сумма пеней не может превышать сумму долга — раньше пени могли накопиться больше самой недоимки. Если за год набежал долг меньше 500 рублей, Социальный фонд пришлёт требование один раз в конце года, а не каждый квартал."},{"t":"h","text":"6. Ограничения для маркетплейсов"},{"t":"p","text":"В Госдуме предложили запретить площадкам повышать комиссии для продавцов чаще одного раза в квартал и обязать уведомлять об изменениях за 45 дней."},{"t":"h","text":"7. Налог на участки под гостевыми домами — до 1,5%"},{"t":"p","text":"Если участок под ИЖС, ЛПХ или садоводство используется для бизнеса — сдаёте комнаты туристам и берёте деньги, — налог считают по ставке до 1,5%. Если дом просто жилой и вы его не сдаёте, ставка льготная 0,3%."},{"t":"p","text":"Данные налоговая берёт из проверок земельного надзора, вашей отчётности, открытых реестров и межведомственных запросов. Предпринимательской деятельностью считается систематическое получение прибыли: сдача пару раз в год знакомым — не бизнес, регулярная аренда — уже бизнес."}],"section":"news","range":"09.03 — 15.03.2026","preview":"Обновлённая РСВ, ограничения для маркетплейсов"};
window.BUHSTART_ARTICLES["novosti-02-08-03-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 02.03–08.03.2026","date":"10 марта 2026","blocks":[{"t":"h","text":"1. Лимит пеней по взносам на травматизм с 1 июля"},{"t":"p","text":"Пени не смогут превышать размер самой задолженности — раньше такого ограничения не было. Кроме того, СФР будет направлять требования об уплате недоимки раз в год, а не ежеквартально, если её сумма вместе с пенями не превышает 500 рублей."},{"t":"h","text":"2. Уведомление о КИК — до 20 марта"},{"t":"p","text":"Организации обязаны подать уведомление о контролируемых иностранных компаниях за 2025 год. Если прибыль КИК превысила 10 млн руб., до 25 марта также нужно представить подтверждающие документы и декларацию по налогу на прибыль. Штраф за непредставление — 500 тыс. рублей."},{"t":"h","text":"3. Новая форма данных для сельхозльгот"},{"t":"p","text":"ФНС утвердила форму сведений из ЕФГИС для подтверждения льгот по земельному и транспортному налогу. С 1 января 2027 года данные будут поступать в налоговую от Минсельхоза, что позволит применять льготы проактивно, без заявления."},{"t":"h","text":"4. Обновлён формат реестра для льгот по налогу на имущество"},{"t":"p","text":"Уточнён состав данных об объектах недвижимости и судах — морских, внутреннего плавания, воздушных, — в отношении которых заявляется льгота. Вступает в силу с 1 января 2027 года."},{"t":"h","text":"5. Минфин предложил смягчить переход к налоговым изменениям для МСП"},{"t":"li","text":"Общепит без НДС: для предприятий на УСН и ПСН предлагается освободить услуги общепита от НДС с 1 апреля по 31 декабря 2026 года, условие о зарплате применяться не будет."},{"t":"li","text":"Переходный период: утратившие право на ПСН смогут получить вычеты по НДС с неиспользованных товаров, бизнес на УСН — уменьшить доходы на сумму НДС с предоплат."},{"t":"li","text":"Льготы по взносам: для обрабатывающих производств уберут условие о доле доходов 70%, доходы по основным и дополнительным видам деятельности разрешат суммировать."},{"t":"li","text":"Выбор режима: совмещавшим ПСН с ОСН при доходе свыше 20 млн руб. разрешат перейти на УСН с 2026 года, уведомив налоговую до 25 апреля."}],"section":"news","range":"02.03 — 08.03.2026","preview":"Общепит без НДС, льготы по взносам, сельхозльготы"};
window.BUHSTART_ARTICLES["novosti-23-02-01-03-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 23.02–01.03.2026","date":"2 марта 2026","blocks":[{"t":"h","text":"1. Налоговый учёт мигрантов с 28 февраля"},{"t":"p","text":"На учёт добавили ИП из ЕАЭС, самозанятых, оказывающих услуги физлицам онлайн, и иностранцев, торгующих или проводящих расчёты. Вместо свидетельств о постановке на учёт теперь выдают выписку из ЕГРН."},{"t":"h","text":"2. НДФЛ с больничных"},{"t":"p","text":"Предлагается освободить от налога пособия по болезни, если их продолжительность не больше 15 дней за полгода: больничный — это компенсация, а не доход."},{"t":"h","text":"3. Декларация по туристическому налогу с 23 апреля"},{"t":"p","text":"В разделе 2 добавили строку 065 для кода ставки: 1 — ставка не менялась, 2 — была дифференциация. Теперь нужно указывать код типа средства размещения."},{"t":"h","text":"4. Консолидированная отчётность с 1 марта"},{"t":"p","text":"Промежуточные компании в группе могут не отчитываться, если их отчётность не нужна пользователям: нет публичных акций, согласны участники, данные есть в отчётности головной компании. Исключения — банки, эмитенты, отдельные АО и ФГУП."},{"t":"h","text":"5. Компенсации удалённым работникам и взносы"},{"t":"p","text":"Компенсации за технику для дистанционных работников освободили от взносов — по аналогии с НДФЛ. Право мигрантов на пособия теперь считают по начисленным, а не уплаченным взносам. Для ИП с договорами ГПХ вводится беззаявительная регистрация. Многодетным сохранят пособие, если доход превысил лимит незначительно."}],"section":"news","range":"23.02 — 01.03.2026","preview":"Туристический налог, консолидированная отчётность"};
window.BUHSTART_ARTICLES["novosti-16-22-02-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 16.02–22.02.2026","date":"25 февраля 2026","blocks":[{"t":"h","text":"1. Не получилось перейти на АвтоУСН — остаётесь на старом режиме"},{"t":"p","text":"Если вы подали заявление, но налоговая нашла причину для отказа, вы просто останетесь на прежней системе налогообложения. Писать дополнительные заявления не нужно."},{"t":"h","text":"2. В Думе предложили новый налог на роскошь"},{"t":"p","text":"Недвижимость дороже 350 млн рублей — ставка 3–4% от кадастровой стоимости. Автомобили дороже 20 млн рублей — 1–4% от цены покупки. Яхты и самолёты дороже 50 млн рублей — 1–4%. Платить нужно будет один раз при регистрации или в течение месяца после покупки."},{"t":"h","text":"3. Курской области продлили отсрочку по налогам"},{"t":"p","text":"Жители и предприятия приграничных районов получили ещё год: налоги за 2024–2026 годы можно заплатить до 1 декабря 2027 года. Для бизнеса предусмотрена рассрочка."},{"t":"h","text":"4. Вычет за спорт — до 19,5 тыс. рублей"},{"t":"p","text":"За 2024 и 2025 годы максимальная сумма возврата 19 500 рублей. Услуги должны оказывать компании из специального списка правительства. С 2026 года вычет можно получить не только за себя и детей, но и за родителей-пенсионеров. Оформить можно через Госуслуги, работодателя или сайт ФНС."},{"t":"h","text":"5. Больше запретов на продажу маркированных товаров"},{"t":"p","text":"Система «Честный знак» будет блокировать продажу большего числа товаров: в список добавили автомобильные жидкости, бакалею, косметику и бытовую химию. Их нельзя будет продать, если нет маркировки или истёк срок годности."},{"t":"h","text":"6. Штрафы за невыдачу чеков вырастут в разы"},{"t":"p","text":"Для организаций минимальный штраф за работу без кассы вырастет с 30 тыс. до 150 тыс. рублей, за невыдачу чека — с 10 тыс. до 50 тыс. ИП будут штрафовать так же, как крупные компании, чтобы наказание зависело от тяжести нарушения, а не от статуса."},{"t":"h","text":"7. Что меняется с 1 июля и 1 сентября 2026 года"},{"t":"li","text":"С компенсации удалёнщикам за использование техники не нужно платить взносы на травматизм — если она не больше 35 рублей в день или подтверждена чеками."},{"t":"li","text":"Больше не надо сообщать в СФР про обособленные подразделения: их создание, закрытие, смену адреса и закрытие счетов."},{"t":"li","text":"Данные о стаже уходящего на пенсию сотрудника нужно отправлять за 3 рабочих дня вместо 3 календарных."},{"t":"li","text":"С 1 сентября в отчётах по договорам ГПХ нужно отдельно указывать, есть ли условие о взносах на травматизм."},{"t":"p","text":"Пособия многодетным: если доход превысил прожиточный минимум меньше чем на 10%, пособие всё равно оставят. Правило действует с 1 января 2026 года, ранее вынесенные отказы пересмотрят автоматически."}],"section":"news","range":"16.02 — 22.02.2026","preview":"Отказ в АвтоУСН, новые запреты «Честного знака»"};
window.BUHSTART_ARTICLES["novosti-08-15-02-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 08.02–15.02.2026","date":"19 февраля 2026","blocks":[{"t":"h","text":"1. Министерствам разрешат самим составлять налоговые списки"},{"t":"p","text":"Минфин составит перечни тех, кто может не платить НДС, и расходов на служебные машины. Минобрнауки решит, какие пробирки и реактивы ввозить беспошлинно. Минспорт вместе с Минфином утвердит список фитнес-услуг для вычета. Минтруд пропишет, какие социальные услуги не облагаются налогом на прибыль."},{"t":"h","text":"2. Что делать, если НДС вырос, а цены в договоре старые"},{"t":"li","text":"Если поставщик хочет поднять цену из-за роста НДС, а покупатель отказывается, суд может увеличить цену только на половину суммы налога."},{"t":"li","text":"Если налоги уплачены единым платежом до суда, деньги в первую очередь спишут в счёт самого старого долга."},{"t":"li","text":"Если несколько собственников продали свои доли земли по одному договору, вычет в 1 млн рублей делится только между ними."},{"t":"li","text":"Отказаться от вычета по НДФЛ можно, только если вы его ещё не получили: вернуть выданные деньги нельзя."},{"t":"h","text":"3. Новая форма декларации по НДС"},{"t":"p","text":"Отчёт за 1 квартал 2026 года сдаётся уже по новой форме до 27 апреля. Появились строки под ставку 22%, расширен список операций без НДС — в него вошли передача товаров для воинских частей и выплата процентов по вкладам в золотых слитках."},{"t":"h","text":"4. Выписка из ЕГРН для фирм подорожает"},{"t":"p","text":"Росреестр предлагает поднять цену электронной выписки для юрлиц с 1400 до 1640 рублей. Для физлиц цена остаётся 700 рублей."},{"t":"h","text":"5. Последний день уплаты взносов за январь — 16 февраля"},{"t":"p","text":"Срок сдвинулся с 15-го, потому что оно выпало на воскресенье. За опоздание штраф 20% от суммы."},{"t":"h","text":"6. Испытательный срок хотят запретить для мам с детьми до 3 лет"},{"t":"p","text":"Сейчас нельзя устанавливать испытание при приёме на работу, если ребёнку нет полутора лет; планку хотят поднять до трёх лет. Пока это проект первого чтения."}],"section":"news","range":"08.02 — 15.02.2026","preview":"Споры о цене при росте НДС, подорожание выписок ЕГРН"};
window.BUHSTART_ARTICLES["novosti-02-08-02-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 02.02–08.02.2026","date":"19 февраля 2026","blocks":[{"t":"h","text":"1. Новая форма заявления по патенту"},{"t":"p","text":"Налоговая утвердила новый бланк заявления о потере права на патент. Это связано с постепенным снижением лимита доходов: 20 млн руб. в 2025–2026 годах, 15 млн в 2026–2027, далее 10 млн. С 2 марта изменится и форма заявления на получение самого патента."},{"t":"h","text":"2. Инициативы для поддержки бизнеса"},{"t":"li","text":"Давать новым плательщикам НДС иммунитет от штрафов за первые ошибки в отчётности."},{"t":"li","text":"Вводить новые налоги или повышать ставки только через год после публикации закона."},{"t":"li","text":"Расширять налоговые льготы для инвестиций и развивать патентную систему."},{"t":"h","text":"3. Срок уплаты налогов на имущество для компаний"},{"t":"p","text":"Организации должны заплатить транспортный, земельный и имущественный налоги за 2025 год не позднее 2 марта 2026 года — срок сдвинут с 28 февраля."},{"t":"h","text":"4. Увеличение социальных налоговых вычетов"},{"t":"p","text":"Депутаты предлагают включить в спортивный вычет путёвки в детские оздоровительные лагеря и увеличить максимальную сумму вычета на лечение, обучение и спорт со 150 000 до 360 000 рублей в год."},{"t":"h","text":"5. УСН и НДС: нельзя смешивать ставки"},{"t":"p","text":"Если компания или ИП на УСН продаёт что-то с НДС, нужно выбрать одну ставку: либо льготную 5% или 7%, либо общую. Применять обе одновременно в зависимости от покупателя нельзя."}],"section":"news","range":"02.02 — 08.02.2026","preview":"Иммунитет от штрафов для новых плательщиков НДС"};
window.BUHSTART_ARTICLES["novosti-26-31-01-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 26.01–31.01.2026","date":"5 февраля 2026","blocks":[{"t":"h","text":"1. Согласие на раскрытие налоговой тайны для ИТ-компаний"},{"t":"p","text":"Крупные аккредитованные ИТ-компании обязаны направить в налоговую согласие на раскрытие фискальной информации Минцифры. Раскрываются факт применения льготных тарифов взносов и ставки по прибыли, средняя численность сотрудников, объём сэкономленных средств и доходы от реализации."},{"t":"p","text":"Касается компаний, которые применяли льготы и имели выручку не менее 800 млн рублей хотя бы в одном из двух предшествующих лет. Последствие неисполнения — аннулирование государственной аккредитации в сфере ИТ."},{"t":"h","text":"2. Новый порядок учёта крупнейших налогоплательщиков"},{"t":"p","text":"ФНС утвердила собственный регламент, забрав полномочия у Минфина. С 26 февраля 2026 года налоговый орган обязан поставить организацию или физлицо на учёт в качестве крупнейшего налогоплательщика в течение 5 рабочих дней с момента решения."},{"t":"h","text":"3. Обновлённые формы по НДС: счёт-фактура, книги покупок и продаж"},{"t":"p","text":"С 1 апреля 2026 года. В счёт-фактуру добавлена строка 5б для суммы и реквизитов ранее полученной предоплаты, которая зачитывается при отгрузке. В книгу покупок — графа 7а для вычета НДС с аванса, полученного продавцом. В книгу продаж — графа 11а для данных из новой строки 5б; уточнены графы для ставок 20%, 18% и 22%."},{"t":"h","text":"4. Законопроекты о сокращённой рабочей неделе для родителей"},{"t":"p","text":"Первый проект: не более 32 часов в неделю — родителю с ребёнком до 14 лет, если второй родитель мобилизован или служит по контракту, а также многодетному родителю. Второй проект: не более 30 часов в неделю одному из родителей с тремя и более детьми, с 1 марта 2026 года."},{"t":"h","text":"5. Льгота по транспортному налогу для участников СВО"},{"t":"p","text":"Утверждены форма уведомления о выбранном транспортном средстве и форма документа о выявлении препятствий для льготы. Вступает в силу 22 февраля 2026 года и применяется к налогу за 2022–2025 годы, то есть льготу можно получить задним числом."}],"section":"news","range":"26.01 — 31.01.2026","preview":"Налоговая тайна для ИТ-компаний, учёт крупнейших налогоплательщиков"};
window.BUHSTART_ARTICLES["novosti-19-25-01-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 19.01–25.01.2026","date":"29 января 2026","blocks":[{"t":"h","text":"1. Трудовой договор можно будет подписывать в мессенджере"},{"t":"p","text":"Минтруд разрабатывает законопроект, который позволит вести кадровый электронный документооборот — запрос справок, согласование отпусков, подписание и расторжение договоров — через мессенджер МАХ. Это дополнительный, а не обязательный канал: существующие способы сохранятся."},{"t":"h","text":"2. Повышение выплат по травмам на производстве"},{"t":"p","text":"С 1 февраля 2026 года выплаты по страхованию от несчастных случаев проиндексируют на 5,6%. Максимальный размер ежемесячной страховой выплаты вырастет до 125 789,16 руб."},{"t":"h","text":"3. Поддержка бизнеса приграничных регионов"},{"t":"p","text":"Предприятиям обрабатывающей промышленности Белгородской, Брянской и Курской областей предоставят льготные займы до 100 млн руб. от 5% годовых на срок до 5 лет и гранты на восстановление деятельности в размере нанесённого ущерба."},{"t":"h","text":"4. ФНС запустила сервис «Мой ОКВЭД»"},{"t":"p","text":"Онлайн-сервис поможет точно подобрать коды ОКВЭД при регистрации бизнеса: использует иерархический метод и прогнозные показатели, визуализируя результат в виде инфографики."},{"t":"h","text":"5. Льгота по налогу на имущество для ИП на спецрежимах"},{"t":"p","text":"Право на льготу имеют ИП на УСН и АУСН — для имущества, используемого в предпринимательской деятельности; на патенте — для объектов, используемых в деятельности по патенту; на ЕСХН — для объектов полного цикла сельхозработ. Льгота не применяется к торгово-офисной недвижимости из региональных перечней."},{"t":"p","text":"ФНС предоставляет льготу автоматически, если имеет подтверждающие данные. Если данных недостаточно, ИП должен подать заявление и документы в I квартале 2026 года, до рассылки налоговых уведомлений. Бремя подтверждения права на льготу лежит на налогоплательщике."}],"section":"news","range":"19.01 — 25.01.2026","preview":"Кадровый ЭДО в мессенджере, индексация выплат по травматизму"};
window.BUHSTART_ARTICLES["novosti-01-12-01-2026"] = {"tag":"Новости законодательства","title":"Новости законодательства 01.01–12.01.2026","date":"12 января 2026","blocks":[{"t":"h","text":"1. 12 января — последний день для перехода на УСН"},{"t":"p","text":"Если вы думали или передумали в связи с последними документами правительства, заявление нужно подать до этой даты."},{"t":"h","text":"2. Маркировка детского питания — эксперимент"},{"t":"p","text":"С 12 января 2026 года стартует добровольный эксперимент «Честного знака» для молочной продукции для детей до 3 лет и консервированной продукции для детей до года. Участие добровольное до 31 октября 2026 года, коды предоставляются бесплатно."},{"t":"h","text":"3. Новые признаки подозрительных операций"},{"t":"li","text":"Переводы самому себе свыше 200 тыс. руб. через СБП с последующей попыткой перевода другому лицу, если ранее переводов ему не было полгода."},{"t":"li","text":"Смена SIM-карты или номера телефона для входа в банк без подтверждения принадлежности номера."},{"t":"li","text":"Использование новых или нехарактерных интернет-провайдеров и приложений, скрывающих данные."},{"t":"li","text":"Внесение наличных через банкомат с цифровой картой в течение 24 часов после зарубежного перевода свыше 100 тыс. руб."},{"t":"h","text":"4. Штрафы для УСН по первой декларации НДС"},{"t":"p","text":"В течение 2026 года бизнес на УСН, впервые ставший плательщиком НДС, не будет оштрафован за опоздание со сдачей первой декларации по НДС."},{"t":"h","text":"5. Ставка НДС в чеках после повышения до 22%"},{"t":"p","text":"Основная ставка с 1 января 2026 года — 22%. Старая ставка 20% в чеке допускается только в отдельных случаях: возврат товара, купленного до 2026 года, коррекция чека за прошлый расчёт, оплата в 2026 году за товар или услугу, полученные раньше. ККТ должна быть обновлена; в I квартале 2026 года ФНС не будет штрафовать за старую ставку, пока идёт обновление ПО."},{"t":"h","text":"6. Пополнение чужого ЕНС"},{"t":"p","text":"С 1 сентября 2026 года запрещено пополнять ЕНС другого лица, если у него нет налоговой обязанности: деньги вернутся отправителю. Также прямо прописана возможность частичного зачёта средств с ЕНС."}],"section":"news","range":"01.01 — 12.01.2026","preview":"Последний день перехода на УСН, маркировка детского питания"};
window.BUHSTART_ARTICLES["novosti-22-28-12-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 22.12–28.12.2025","date":"30 декабря 2025","blocks":[{"t":"h","text":"1. НДС на иностранные интернет-покупки"},{"t":"p","text":"Для товаров из-за рубежа, купленных на маркетплейсах, хотят ввести НДС. Платёж ляжет на иностранных продавцов или российские площадки. Ставка будет расти постепенно: 5% в 2027 году, 10% в 2028, 15% в 2029 и полные 20% с 2030 года."},{"t":"h","text":"2. Повышенная компенсация за задержку зарплаты"},{"t":"p","text":"Депутаты предложили увеличить компенсацию в 5 раз: вместо не менее 1/150 ключевой ставки ЦБ от невыплаченной суммы в день — не менее 1/30."},{"t":"h","text":"3. Ставка НДФЛ при непропорциональном распределении дивидендов"},{"t":"p","text":"Если компания выплачивает прибыль участникам не пропорционально их долям, такие выплаты формально не считаются дивидендами по НК. Но ФНС разъясняет: эти доходы всё равно облагаются НДФЛ как доходы от долевого участия по стандартным ставкам 13%, или 15% при доходе свыше 5 млн рублей в год."},{"t":"h","text":"4. Сверхурочные: увеличение лимита"},{"t":"p","text":"Предлагают разрешить до 240 часов в год вместо 120, но только если это прописано в коллективном договоре. Лимит 120 часов сохранится для госучреждений и работ с вредными условиями классов 3.3 и 3.4. Для работников классов 3.1 и 3.2 нужно письменное согласие и отсутствие медицинских противопоказаний. Все, кого привлекают к сверхурочным свыше 120 часов, получают один оплачиваемый день на диспансеризацию."},{"t":"h","text":"5. Электронные инструктажи по охране труда"},{"t":"p","text":"С 1 сентября 2027 года журналы инструктажей можно будет вести электронно через платформу «Работа в России» с электронной подписью — сейчас только на бумаге."},{"t":"h","text":"6. Расходы на трудоустройство инвалидов"},{"t":"p","text":"Их можно будет учитывать при расчёте налога на прибыль."},{"t":"h","text":"7. Форматы фискальных документов под ставку 22%"},{"t":"p","text":"ФНС дополнила таблицу значений реквизита «ставка НДС»: код 11 — ставка 22%, код 12 — расчётная 22/122. Приказ действует с 5 января 2026 года."}],"section":"news","range":"22.12 — 28.12.2025","preview":"Компенсация за задержку зарплаты, НДФЛ с непропорциональных дивидендов"};
window.BUHSTART_ARTICLES["novosti-15-21-12-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 15.12–21.12.2025","date":"23 декабря 2025","blocks":[{"t":"h","text":"1. Новая строка в счетах-фактурах в 1С"},{"t":"p","text":"С 18 декабря в форме счёта-фактуры появилась строка 5б — для реквизитов авансового счёта-фактуры при отгрузке в счёт аванса, полученного в предыдущем квартале. Требование действует с 1 января 2026 года, бумажная форма бланка не меняется до 1 апреля 2026 года."},{"t":"h","text":"2. Обновлены формы персонифицированного учёта в СФР"},{"t":"p","text":"Утверждены новые формы АДВ-1, АДВ-2, АДВ-3 и СЗВ-К. В СЗВ-К реквизит «Тип формы» переименован в «Тип сведений», добавлены данные о страхователе: регистрационный номер СФР, ИНН, КПП, краткое наименование. Приказ вступает в силу 30 декабря 2025 года."},{"t":"h","text":"3. Ключевая ставка снижена до 16%"},{"t":"p","text":"С 22 декабря 2025 года."},{"t":"h","text":"4. Подтверждение бесплатной помощи для СВО"},{"t":"p","text":"Бесплатную передачу товаров и услуг для нужд СВО — не облагаемую НДС и учитываемую в расходах по прибыли — можно подтвердить первичным документом, оформляющим эту операцию."},{"t":"h","text":"5. Эксперимент по больничным для самозанятых"},{"t":"p","text":"С 2026 по 2028 год пройдёт эксперимент по добровольным больничным для плательщиков НПД. Нужно зарегистрироваться в СФР и платить ежемесячный взнос 3,84% от выбранной страховой суммы — 35 или 50 тыс. руб. Заявление можно подать до 30 сентября 2027 года. Право на пособие возникает, как правило, после 6 месяцев уплаты взносов, размер зависит от стажа."}],"section":"news","range":"15.12 — 21.12.2025","preview":"Ключевая ставка 16%, новые формы персучёта в СФР"};
window.BUHSTART_ARTICLES["novosti-08-14-12-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 08.12–14.12.2025","date":"17 декабря 2025","blocks":[{"t":"h","text":"1. АвтоУСН: 16 новых регионов"},{"t":"p","text":"С 1 января 2026 года к эксперименту присоединятся 16 новых регионов. Режимом уже пользуются 41,5 тыс. предпринимателей, более 14 тыс. подали уведомления о переходе с 2026 года."},{"t":"p","text":"Условия: доход не более 60 млн руб. в год, не более 5 сотрудников — только налоговые резиденты РФ, счёт в уполномоченном банке. Налог 8% или 20% включая страховые взносы, отчётность упрощена. Переход возможен с первого числа любого месяца."},{"t":"h","text":"2. Налоговый вычет на спорт для родителей-пенсионеров"},{"t":"p","text":"С 2026 года взрослые дети смогут получить вычет по НДФЛ до 19 500 руб., оплатив физкультурно-оздоровительные услуги для родителей-пенсионеров. Услуги должны входить в перечень Правительства и оказываться аккредитованной организацией."},{"t":"h","text":"3. Разъяснения по НДС и НДФЛ"},{"t":"li","text":"Товарами при обложении НДС признаются детали, переданные взамен бракованных."},{"t":"li","text":"Штраф налогового агента за неперечисление НДФЛ исчисляется от всей суммы, подлежавшей удержанию."},{"t":"li","text":"Право собственности на дом, перешедшее от незавершённого строительства, сохраняет минимальный срок владения для имущественного вычета."},{"t":"h","text":"4. Квоты на иностранных работников на 2026 год"},{"t":"p","text":"Общие квоты снижены для ряда отраслей: строительство до 50%, овощеводство до 40%. Запрещено привлекать иностранцев для продажи алкоголя и табака в специализированных магазинах, кроме Москвы, где квота 15%. В некоторых регионах установлены полные запреты на труд иностранцев в отдельных сферах."},{"t":"p","text":"Штрафы за нарушение: для юрлиц до 1 млн руб. или приостановка деятельности на срок от 14 до 90 суток, для должностных лиц от 45 до 50 тыс. рублей."}],"section":"news","range":"08.12 — 14.12.2025","preview":"Вычет на спорт для родителей-пенсионеров, разъяснения по НДС и НДФЛ"};
window.BUHSTART_ARTICLES["novosti-01-07-12-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 01.12–07.12.2025","date":"9 декабря 2025","blocks":[{"t":"h","text":"1. Маркировка смартфонов и светотехники"},{"t":"p","text":"Утверждены правила маркировки для смартфонов, ламп, розеток, светодиодов и другой радиоэлектронной продукции. Маркировка станет обязательной с 1 мая 2026 года. Подача данных об обороте — с 1 декабря 2026 года, о выводе из оборота — с 1 марта 2027 года."},{"t":"h","text":"2. Выручка при продаже акционных товаров через маркетплейс"},{"t":"p","text":"ФНС разъяснила, как продавцам определять выручку, если окончательный размер скидки становится известен из отчёта площадки. Отчёты маркетплейсов поступают раньше сроков сдачи деклараций — до 25 числа следующего месяца, — поэтому у продавца есть время для корректного расчёта налоговой базы."},{"t":"h","text":"3. Коды доходов и вычетов для АУСН"},{"t":"p","text":"ФНС рекомендовала организациям и ИП на автоматизированной УСН временные коды вида дохода и вычета для представления информации в банки по НДФЛ и взносам. Рекомендации действуют до внесения изменений в приказ ФНС."},{"t":"h","text":"4. Пени при утрате права на патент"},{"t":"p","text":"При утрате права на ПСН ИП переходит на общий режим и платит налоги как вновь зарегистрированный предприниматель. Пени не начисляются за несвоевременную уплату налогов, относящихся к периоду действия патента, — только с даты утраты права, если ИП не уплатит авансовые платежи за последующие периоды."},{"t":"h","text":"5. Новый порядок присвоения ИНН"},{"t":"p","text":"С 1 января 2026 года вводится новый цифровой порядок. Бумажные свидетельства ИНН выдаваться не будут. Изменения коснутся всех: от новорождённых до организаций."}],"section":"news","range":"01.12 — 07.12.2025","preview":"Выручка при продаже акционных товаров, пени при утрате права на патент"};
window.BUHSTART_ARTICLES["novosti-24-30-11-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 24.11–30.11.2025","date":"3 декабря 2025","blocks":[{"t":"h","text":"1. Подписаны поправки в Налоговый кодекс на 2026–2028 годы"},{"t":"li","text":"НДС: ставка повышается с 20% до 22% с 2026 года."},{"t":"li","text":"УСН: лимит дохода для перехода на НДС будет поэтапно снижаться с 20 млн руб. в 2026 году до 10 млн в 2028."},{"t":"li","text":"Акцизы: повышение ставок на спирт, алкоголь, табак, никотин- и сахаросодержащую продукцию."},{"t":"li","text":"Госпошлины: увеличение за регистрацию воздушных судов и лицензии на алкоголь, новые пошлины за лицензии в сфере безопасности и экспортного контроля."},{"t":"li","text":"Налог на игорный бизнес переходит из регионального в федеральный, фиксированные ставки повышаются. Для букмекеров — 7% от чистой прибыли."},{"t":"li","text":"Страховые взносы для ИТ-компаний: тариф повышается с 7,6% до 15%."},{"t":"h","text":"2. Новый порядок налоговых отсрочек"},{"t":"p","text":"С 24 декабря решения по отсрочке, рассрочке или инвестиционному налоговому кредиту на сумму свыше 1 млрд рублей принимаются только по согласованию с ФНС России; до 1 млрд — инспекцией самостоятельно."},{"t":"h","text":"3. Документы по контролируемым сделкам — до 1 декабря"},{"t":"p","text":"Нужно представить в ФНС документы, подтверждающие рыночный уровень цен в контролируемых сделках за 2024 год по сырьевым товарам: нефть, металлы, драгоценные камни и другое."},{"t":"h","text":"4. Эквайринг и процессинг будут облагаться НДС"},{"t":"p","text":"С 2026 года обслуживание карт и их обработка исключены из перечня необлагаемых банковских операций — ставка 22%. Налог начисляется на услугу процессинга, а не на сам платёж. Эксперты предупреждают о росте тарифов и удорожании безналичных расчётов."},{"t":"p","text":"Без НДС остаются открытие счетов и вкладов, переводы, кассовое обслуживание, операции с валютой и драгметаллами. Владельцев карт напрямую налог не касается."},{"t":"h","text":"5. Возможное расширение туристического налога"},{"t":"p","text":"В 2026 году может быть рассмотрено распространение налога на владельцев квартир и домов, сдающих жильё посуточно. Сейчас его платят только классифицированные средства размещения — отели, хостелы, санатории."}],"section":"news","range":"24.11 — 30.11.2025","preview":"Эквайринг с НДС, новый порядок отсрочек"};
window.BUHSTART_ARTICLES["novosti-17-23-11-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 17.11–23.11.2025","date":"25 ноября 2025","blocks":[{"t":"h","text":"1. Тарифы на травматизм останутся прежними до 2028 года"},{"t":"p","text":"Госдума установила тарифы на 2026–2028 годы: от 0,2% до 8,5% в зависимости от класса профессионального риска. Продлена льгота для работодателей, трудоустраивающих инвалидов I, II или III групп: за них взносы уплачиваются в размере 60% от установленного тарифа."},{"t":"h","text":"2. Эксперимент по маркировке мясной продукции"},{"t":"p","text":"С 24 ноября 2025 года стартует добровольный эксперимент «Честного знака»: колбасные и мясные изделия — до 28 февраля 2026 года, полуфабрикаты из птицы и замороженная продукция — до 31 августа 2026 года."},{"t":"h","text":"3. Налоговики помогут выявлять подмену трудовых отношений"},{"t":"p","text":"Минтруд планирует привлекать ФНС для выявления компаний, подменяющих трудовые отношения договорами с самозанятыми. В Роструд будут передавать данные об организациях, которые взаимодействуют более чем с 35 самозанятыми со средним доходом от компании свыше 35 тыс. руб. и долей 90% и выше, либо работают более чем с 10 самозанятыми, бывшими в прошлом квартале штатными сотрудниками."}],"section":"news","range":"17.11 — 23.11.2025","preview":"Эксперимент по маркировке мясной продукции"};
window.BUHSTART_ARTICLES["novosti-10-16-11-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 10.11–16.11.2025","date":"19 ноября 2025","blocks":[{"t":"h","text":"1. Налоговые изменения для бизнеса и льготы"},{"t":"p","text":"Депутаты рассмотрят пакет поправок к бюджету и налогам на 2026–2028 годы. Бизнес на УСН обяжут платить НДС при более низких годовых доходах: лимит будет постепенно снижаться и к 2028 году составит 10 млн рублей. Патент останется для магазинов и грузоперевозок, продажа прав на российское ПО не будет облагаться НДС."},{"t":"p","text":"Новые льготы: земские тренеры освободятся от НДФЛ с выплат, Герои России получат льготу по транспортному налогу, граждане на территориях с ЧС или режимом КТО не будут платить налог на имущество и землю."},{"t":"h","text":"2. Повышение коэффициентов-дефляторов на 2026 год"},{"t":"li","text":"Для УСН коэффициент вырастет до 1,090, что снизит лимит доходов для применения режима."},{"t":"li","text":"Для ПСН — 1,253, что приведёт к удорожанию патентов."},{"t":"li","text":"Для торгового сбора — 2,165, что увеличит сумму платежа."},{"t":"h","text":"3. Больничные для самозанятых с 2026 года"},{"t":"p","text":"Нужно заключить договор с СФР и платить взносы: около 1344 руб. в месяц для выплаты 35 000 руб. или 1920 руб. для выплаты 50 000 руб. Право на выплату появится после 6 месяцев уплаты взносов, размер пособия зависит от стажа."},{"t":"h","text":"4. Система прослеживаемости импортных товаров"},{"t":"p","text":"С 1 сентября 2026 года в России и странах ЕАЭС на постоянной основе заработает электронный контроль за движением товаров после ввоза. Цель — убедиться, что товары используются так, как заявлено, и с них уплачены все налоги и пошлины."},{"t":"h","text":"5. Разъяснения ФНС: почему вырос налог за 2024 год"},{"t":"li","text":"Новая кадастровая оценка зданий и сооружений, применяемая с 2024 года."},{"t":"li","text":"Снят мораторий на использование обновлённой кадастровой стоимости земель."},{"t":"li","text":"В реестр внесли ранее незарегистрированные объекты недвижимости."},{"t":"li","text":"Увеличился список дорогих автомобилей от 10 млн руб. с повышающим коэффициентом 3."},{"t":"p","text":"Крайний срок уплаты большинства налогов на имущество за 2024 год — 1 декабря 2025 года. Для пострадавших на отдельных территориях Курской области срок продлён на 12 месяцев."}],"section":"news","range":"10.11 — 16.11.2025","preview":"Прослеживаемость импорта, разъяснения ФНС по налогам"};
window.BUHSTART_ARTICLES["novosti-01-09-11-2025"] = {"tag":"Новости законодательства","title":"Новости законодательства 01.11–09.11.2025","date":"10 ноября 2025","blocks":[{"t":"h","text":"1. Налоговая льгота для компаний, трудоустраивающих инвалидов"},{"t":"p","text":"Регионам могут разрешить устанавливать пониженную ставку налога на прибыль не выше 13,5% для юрлиц, в штате которых не менее 30% работников-инвалидов."},{"t":"h","text":"2. Свидетельства ИНН для организаций заменят выпиской из ЕГРН"},{"t":"p","text":"С 1 января 2026 года вместо бумажных свидетельств и уведомлений юрлицам будут выдавать выписку из Единого госреестра налогоплательщиков. Ранее выданные документы остаются действительными, структура ИНН и КПП не меняется."},{"t":"h","text":"3. Изменена декларация по налогу на прибыль"},{"t":"p","text":"Скорректированы лист 02, приложение 4 к нему и лист 08; добавлен новый лист 05.1 для операций с цифровой валютой. Новая форма действует с подачи декларации за 2025 год, приказ вступает в силу с 1 января 2026 года."},{"t":"h","text":"4. Повышен лимит для страховых взносов на 2026 год"},{"t":"p","text":"Предельная база увеличена на 8% и составит 2 979 000 рублей. Этот лимит влияет на расчёт больничных и декретных пособий."},{"t":"h","text":"5. Чек нужно печатать, если покупатель не хочет сообщать контакты"},{"t":"p","text":"ФНС напомнила, что вопрос «Нужен ли чек?» некорректен: если клиент отказывается сообщать телефон или e-mail для электронного чека, кассир обязан напечатать бумажный."},{"t":"h","text":"6. Индексация взносов на травматизм для АУСН"},{"t":"p","text":"С 1 января 2026 года фиксированный взнос для плательщиков на автоматизированной УСН составит 2 959 рублей в год против 2 750 рублей в 2025 году."}],"section":"news","range":"01.11 — 09.11.2025","preview":"Выписка из ЕГРН вместо свидетельства ИНН, правила печати чеков"};
window.BUHSTART_ARTICLES["ugolovnaya-otvetstvennost-za-nalogi"] = {"tag":"Новости законодательства","title":"Уголовная ответственность за налоги: кто, когда и как садится","date":"10 ноября 2025","blocks":[{"t":"p","text":"Главный парадокс налоговых преступлений в том, что их почти всегда совершают не «плохие парни» в масках, а обычные предприниматели и директора. Те, кто просто отложил платёж на потом, закрыл кассовый разрыв или решил сэкономить. Но для государства это не оправдание."},{"t":"h","text":"За что именно светит «уголовка»"},{"t":"p","text":"Одно слово: уклонение. То есть умышленное неисполнение обязанности по уплате налогов и сборов. Всё упирается в размеры, и суммы для разных категорий разные."},{"t":"h","text":"Для индивидуальных предпринимателей"},{"t":"p","text":"ИП отвечает как физическое лицо по ст. 198 УК РФ. Точка отсчёта — долг свыше 2,7 млн рублей за три года подряд."},{"t":"h","text":"Для организаций"},{"t":"p","text":"Ответственность по ст. 199 УК РФ. Крупный размер — свыше 18,75 млн рублей за три года подряд, особо крупный — свыше 56,25 млн рублей. Важный нюанс: отвечают не абстрактные активы компании, а конкретные люди — директор и главный бухгалтер."},{"t":"h","text":"Чем грозит"},{"t":"li","text":"Для ИП — максимум лишение свободы до 3 лет."},{"t":"li","text":"Для директора или бухгалтера в особо крупном размере — до 5 лет колонии."},{"t":"p","text":"И это не считая штрафов, запретов занимать должности и судимости, которая останется навсегда."},{"t":"h","text":"Есть ли «спасательный круг»"},{"t":"p","text":"Да. Если долг не в особо крупном размере и налогоплательщик добровольно погасил всю недоимку, пеню и штрафы, уголовное дело не возбуждается, а возбуждённое прекращается. Это ваш главный козырь, но действовать нужно быстро."},{"t":"p","text":"Лучшая защита от уголовной ответственности — чистая бухгалтерия и своевременная уплата налогов."}],"section":"news","range":"Разбор","preview":"Пороги по ст. 198 и 199 УК РФ, кто отвечает в компании"};
